window.GAM_QT={"ver":"2026-10-28","dm":[{"id":"phucvu","ten":"Quy trình phục vụ","tem":["Quy trình","phục vụ"],"nhan":"Phục vụ · tiếp thực · thu ngân","icon":"khay","nhom":[{"ten":"","bai":["tinhthan","qt1","qt2","qt3","qt4","qt5","qt6","qt7","qt9","caunoi"]}]},{"id":"quay","ten":"Quy trình đứng quầy","tem":["Đứng","quầy"],"nhan":"Đầu ca · trong ca · cuối ca","icon":"ly","nhom":[{"ten":"","bai":["quay1","quay2","quay3","quay4"]}]},{"id":"bep","ten":"Bếp & món","tem":["Bếp","& món"],"nhan":"Thời gian ra món · món trễ","icon":"noi","nhom":[{"ten":"","bai":["thamchieu","qt7"]}],"soan":"Quy trình bếp và công thức món đang soạn, sẽ cập nhật sau."},{"id":"tinhhuong","ten":"Cẩm nang xử lý tình huống","tem":["Xử lý","tình huống"],"nhan":"30 tình huống · cách nói","icon":"loi","nhom":[{"ten":"","bai":["cachnoi"]},{"ten":"Nhóm 1 – Món ăn","gioi":"Chuyện về món thì xử lý món trước, xin lỗi bằng một câu, và luôn báo khách bao lâu nữa có món.","bai":["th1","th2","th3","th4","th5","th6"]},{"ten":"Nhóm 2 – Giá và bill","gioi":"Không tranh luận về giá và không tự giảm giá. Ghi nhận, dò lại cùng khách, chuyện tiền bạc để quản lý quyết.","bai":["th7","th8","th9"]},{"ten":"Nhóm 3 – Khách bực và yêu cầu ngoài quy định","gioi":"Khách đang nóng thì mình nghe trước, nói sau. Mình dùng giọng nhỏ hơn khách, không bảo khách bình tĩnh.","bai":["th10","th11"]},{"ten":"Nhóm 4 – An toàn, sức khỏe và review","gioi":"Hỏi sức khỏe khách trước, hỏi chuyện sau. Không tự kết luận nguyên nhân, không chối, không hứa bồi thường — việc đó quản lý làm.","bai":["th12","th13","th14"]},{"ten":"Tình huống bổ sung – tại quán","gioi":"","bai":["th15","th16","th17","th18","th19","th20","th21","th22","th23","th24","th25"]},{"ten":"Tình huống bổ sung – thanh toán, giờ đóng bếp, giao hàng, mạng xã hội","gioi":"Chuyện tiền và chuyện trên mạng luôn báo quản lý. Nhân viên giữ lịch sự, không kết luận khách đúng hay sai.","bai":["th26","th27","th28","th29","th30"]},{"ten":"Tra nhanh","bai":["tranhanh"]}]},{"id":"quanly","ten":"Dành cho quản lý","tem":["Quản","lý"],"nhan":"Bàn đặt · checklist · báo cáo","icon":"bang","nhom":[{"ten":"","bai":["qt9","checklist","baocao","tranhanh"]}]}],"bai":{"tinhthan":{"so":"★","ten":"Tinh thần chung","nhan":"","html":"<p>Ở Gặm, khách bước vào là khách của cả quán, không phải của riêng bạn đứng cổng. Ai mặc áo Gặm — phục vụ, tiếp thực, quản lý — cũng là người đón và tiễn khách.</p>\n<p>Ba điều ai cũng phải nhớ:</p>\n<ol>\n<li><strong>Gặp đâu chào đó.</strong> Gặp khách ở bất kỳ chỗ nào trong quán thì chào ngay chỗ đó: một cái cúi đầu, một nụ cười, hoặc câu \"Dạ Gặm xin chào\" / \"Dạ Gặm cảm ơn\".</li>\n<li><strong>Khách không phải đi tìm mình.</strong> Mình luôn để mắt tới bàn mình phụ trách, khách vừa giơ tay là mình đã thấy.</li>\n<li><strong>Câu nào cũng mở đầu bằng \"Dạ\".</strong> Nói ngắn, rõ, nhìn vào khách và cười thật.</li>\n</ol>","toc":[],"text":"Ở Gặm, khách bước vào là khách của cả quán, không phải của riêng bạn đứng cổng. Ai mặc áo Gặm — phục vụ, tiếp thực, quản lý — cũng là người đón và tiễn khách. Ba điều ai cũng phải nhớ: Gặp đâu chào đó. Gặp khách ở bất kỳ chỗ nào trong quán thì chào ngay chỗ đó: một cái cúi đầu, một nụ cười, hoặc câu \"Dạ Gặm xin chào\" / \"Dạ Gặm cảm ơn\". Khách không phải đi tìm mình. Mình luôn để mắt tới bàn mình phụ trách, khách vừa giơ tay là mình đã thấy. Câu nào cũng mở đầu bằng \"Dạ\". Nói ngắn, rõ, nhìn vào khách và cười thật.","h":"31cb8d1a"},"qt1":{"so":"QT1","ten":"Đón khách ở cổng","nhan":"","html":"<p>Khách vừa tới cổng là phải được chào ngay, rồi mình hỏi số người, hỏi đặt bàn và dẫn khách tới tận bàn.</p>\n<p class=\"lam\"><strong>Ai làm:</strong> bạn đứng cổng. Không có ai ở cổng thì bạn phục vụ hoặc quản lý đứng gần nhất ra đón.</p>\n<ol>\n<li><strong>Chào.</strong> Nhìn khách, cười, cúi đầu nhẹ: <em class=\"noi\">Dạ Gặm xin chào anh chị ạ!</em></li>\n<li><strong>Hỏi số người.</strong> <em class=\"noi\">Dạ anh chị mình đi mấy người ạ?</em></li>\n<li><strong>Hỏi đặt bàn.</strong> <em class=\"noi\">Dạ anh chị mình có đặt bàn trước chưa ạ?</em><ul>\n<li>Có đặt: hỏi tên hoặc số điện thoại, dò lại bàn đã giữ rồi dẫn khách tới đúng bàn đó.</li>\n<li>Chưa đặt: chọn bàn vừa với số người, ưu tiên bàn trống ở khu đang có bạn phục vụ trực.</li>\n</ul>\n</li>\n<li><strong>Dẫn bàn.</strong> Đi trước khách 1–2 bước, tay chỉ hướng: <em class=\"noi\">Dạ mời anh chị đi lối này ạ.</em> Đi vừa chân khách, không đi quá nhanh.</li>\n<li><strong>Giới thiệu bàn.</strong> Tới nơi, tay chỉ vào bàn: <em class=\"noi\">Dạ anh chị ngồi bàn này nha.</em> Đợi khách ngồi xong rồi chuyển sang Quy trình 2.</li>\n</ol>\n<div class=\"khong\"><p><strong>Tránh:</strong></p><ul>\n<li>Để khách đứng ở cổng mà không ai chào.</li>\n<li>Hỏi cộc lốc \"Mấy người?\" mà thiếu \"Dạ\" và \"anh chị\".</li>\n<li>Chỉ tay về phía bàn rồi để khách tự đi tới.</li>\n</ul></div>\n","toc":[],"text":"Khách vừa tới cổng là phải được chào ngay, rồi mình hỏi số người, hỏi đặt bàn và dẫn khách tới tận bàn. Ai làm: bạn đứng cổng. Không có ai ở cổng thì bạn phục vụ hoặc quản lý đứng gần nhất ra đón. Chào. Nhìn khách, cười, cúi đầu nhẹ: Dạ Gặm xin chào anh chị ạ! Hỏi số người. Dạ anh chị mình đi mấy người ạ? Hỏi đặt bàn. Dạ anh chị mình có đặt bàn trước chưa ạ? Có đặt: hỏi tên hoặc số điện thoại, dò lại bàn đã giữ rồi dẫn khách tới đúng bàn đó. Chưa đặt: chọn bàn vừa với số người, ưu tiên bàn trống ở khu đang có bạn phục vụ trực. Dẫn bàn. Đi trước khách 1–2 bước, tay chỉ hướng: Dạ mời anh chị đi lối này ạ. Đi vừa chân khách, không đi quá nhanh. Giới thiệu bàn. Tới nơi, tay chỉ vào bàn: Dạ anh chị ngồi bàn này nha. Đợi khách ngồi xong rồi chuyển sang Quy trình 2. Tránh: Để khách đứng ở cổng mà không ai chào. Hỏi cộc lốc \"Mấy người?\" mà thiếu \"Dạ\" và \"anh chị\". Chỉ tay về phía bàn rồi để khách tự đi tới.","h":"64ebcfe8"},"qt2":{"so":"QT2","ten":"Gửi menu và order","nhan":"","html":"<p>Gửi menu xong thì lùi lại cho khách thoải mái chọn, nhưng mắt vẫn ở bàn. Quá 4–5 phút khách chưa gọi thì mình chủ động tới tư vấn.</p>\n<p class=\"lam\"><strong>Ai làm:</strong> bạn phục vụ phụ trách khu đó.</p>\n<ol>\n<li><strong>Gửi menu.</strong> Đưa menu bằng hai tay: <em class=\"noi\">Dạ em gửi anh chị menu ạ.</em></li>\n<li><strong>Lùi lại.</strong> Lùi về phía sau, đứng ở chỗ nhìn thấy bàn. Không đứng sát bàn hối khách, cũng không đi mất.</li>\n<li><strong>Để ý trong 3–4 phút đầu.</strong> Khách giơ tay hoặc nhìn quanh tìm người → tới ngay: <em class=\"noi\">Dạ anh chị đã chọn được món chưa ạ?</em></li>\n<li><strong>Quá 4–5 phút chưa gọi → có thể là khách mới.</strong> Mình tự tới, không đợi khách kêu:<ul>\n<li><em class=\"noi\">Dạ anh chị chọn được món chưa ạ? Anh chị có cần em tư vấn gì không ạ?</em></li>\n<li>Chỉ vào menu: <em class=\"noi\">Dạ trên menu, những món có đánh dấu ngôi sao là những món khách thích ăn nhất ở Gặm đó ạ. Anh chị có thể tham khảo ở đây nha.</em></li>\n</ul>\n</li>\n<li><strong>Order trên điện thoại.</strong> Ghi từng món vào điện thoại ngay tại bàn.</li>\n<li><strong>Đọc lại order.</strong> Trước khi gửi, đọc lại cho khách: <em class=\"noi\">Dạ em xin đọc lại món của anh chị ạ…</em> Khách xác nhận rồi mới gửi.</li>\n<li><strong>Kết thúc.</strong> <em class=\"noi\">Dạ em cảm ơn, anh chị đợi em một chút ạ.</em></li>\n</ol>\n<figure class=\"sodo\"><img alt=\"luồng gửi menu và order · 1 nhánh rẽ\" loading=\"lazy\" src=\"img/qt2.png\"/></figure>\n<p>Dù khách tự gọi hay mình tới tư vấn, hai nhánh đều kết thúc bằng order trên điện thoại và đọc lại món cho khách.</p>\n<div class=\"khong\"><p><strong>Tránh:</strong></p><ul>\n<li>Đứng ngay cạnh bàn khi khách đang lật menu.</li>\n<li>Để khách phải kêu lớn hoặc đứng dậy đi tìm người order.</li>\n<li>Gửi order mà chưa đọc lại cho khách.</li>\n</ul></div>\n","toc":[],"text":"Gửi menu xong thì lùi lại cho khách thoải mái chọn, nhưng mắt vẫn ở bàn. Quá 4–5 phút khách chưa gọi thì mình chủ động tới tư vấn. Ai làm: bạn phục vụ phụ trách khu đó. Gửi menu. Đưa menu bằng hai tay: Dạ em gửi anh chị menu ạ. Lùi lại. Lùi về phía sau, đứng ở chỗ nhìn thấy bàn. Không đứng sát bàn hối khách, cũng không đi mất. Để ý trong 3–4 phút đầu. Khách giơ tay hoặc nhìn quanh tìm người → tới ngay: Dạ anh chị đã chọn được món chưa ạ? Quá 4–5 phút chưa gọi → có thể là khách mới. Mình tự tới, không đợi khách kêu: Dạ anh chị chọn được món chưa ạ? Anh chị có cần em tư vấn gì không ạ? Chỉ vào menu: Dạ trên menu, những món có đánh dấu ngôi sao là những món khách thích ăn nhất ở Gặm đó ạ. Anh chị có thể tham khảo ở đây nha. Order trên điện thoại. Ghi từng món vào điện thoại ngay tại bàn. Đọc lại order. Trước khi gửi, đọc lại cho khách: Dạ em xin đọc lại món của anh chị ạ… Khách xác nhận rồi mới gửi. Kết thúc. Dạ em cảm ơn, anh chị đợi em một chút ạ. Dù khách tự gọi hay mình tới tư vấn, hai nhánh đều kết thúc bằng order trên điện thoại và đọc lại món cho khách. Tránh: Đứng ngay cạnh bàn khi khách đang lật menu. Để khách phải kêu lớn hoặc đứng dậy đi tìm người order. Gửi order mà chưa đọc lại cho khách.","h":"2265efbd"},"qt3":{"so":"QT3","ten":"Bưng món (tiếp thực)","nhan":"","html":"<p>Món ra tới bàn phải đúng bàn, đúng món, đủ đồ ăn kèm, và khách phải nghe được tên món mình vừa đặt xuống.</p>\n<p class=\"lam\"><strong>Ai làm:</strong> bạn tiếp thực; lúc đông thì phục vụ bưng phụ.</p>\n<ol>\n<li><strong>Nhận món ở quầy ra món, không vào bếp lấy.</strong> Quầy có 2 bạn:<ul>\n<li>Bạn ra món: ra chân gà và các món nước.</li>\n<li>Bạn đọc món: lấy món từ bếp, đọc món và đọc lại cho tiếp thực.</li>\n<li>Tiếp thực đứng chờ ở quầy, nghe bạn quầy đọc <strong>số bàn + tên món</strong>, lặp lại để xác nhận rồi mới bưng.</li>\n<li>Kiểm tra đồ ăn kèm (nước chấm, rau, chén đũa nếu cần). Thiếu gì báo quầy ngay, không bưng ra rồi mới quay lại lấy.</li>\n</ul>\n</li>\n<li><strong>Đi tới bàn.</strong> Bưng chắc tay, đi đúng lối. Gặp khách trên đường thì nhường lối và cúi đầu chào (xem Quy trình 4).</li>\n<li><strong>Xin phép lên món.</strong> <em class=\"noi\">Dạ em xin phép lên món ạ.</em> Đặt món từ phía còn trống, không với ngang qua người khách.</li>\n<li><strong>Báo tên món.</strong> <em class=\"noi\">Dạ đây là món ___ của anh chị ạ.</em></li>\n<li><strong>Chúc khách.</strong> <em class=\"noi\">Dạ anh chị dùng ngon miệng ạ.</em></li>\n<li><strong>Món cuối cùng.</strong> <em class=\"noi\">Dạ món của anh chị đã lên đủ rồi ạ. Anh chị cần gì thêm cứ gọi em nha.</em></li>\n<li><strong>Mang đồ dơ về.</strong> Trên đường quay lại quầy, tiện tay thu chén đĩa trống ở bàn đã ăn xong (hỏi khách trước nếu bàn vẫn còn ngồi).</li>\n</ol>\n<div class=\"khong\"><p><strong>Tránh:</strong></p><ul>\n<li>Đặt món xuống rồi đi mà không nói gì.</li>\n<li>Hỏi cả bàn \"Món này của ai?\" — nghe kỹ bạn quầy đọc số bàn để khỏi phải hỏi.</li>\n<li>Bưng món đi ngang khách mà không chào.</li>\n</ul></div>\n","toc":[],"text":"Món ra tới bàn phải đúng bàn, đúng món, đủ đồ ăn kèm, và khách phải nghe được tên món mình vừa đặt xuống. Ai làm: bạn tiếp thực; lúc đông thì phục vụ bưng phụ. Nhận món ở quầy ra món, không vào bếp lấy. Quầy có 2 bạn: Bạn ra món: ra chân gà và các món nước. Bạn đọc món: lấy món từ bếp, đọc món và đọc lại cho tiếp thực. Tiếp thực đứng chờ ở quầy, nghe bạn quầy đọc số bàn + tên món , lặp lại để xác nhận rồi mới bưng. Kiểm tra đồ ăn kèm (nước chấm, rau, chén đũa nếu cần). Thiếu gì báo quầy ngay, không bưng ra rồi mới quay lại lấy. Đi tới bàn. Bưng chắc tay, đi đúng lối. Gặp khách trên đường thì nhường lối và cúi đầu chào (xem Quy trình 4). Xin phép lên món. Dạ em xin phép lên món ạ. Đặt món từ phía còn trống, không với ngang qua người khách. Báo tên món. Dạ đây là món ___ của anh chị ạ. Chúc khách. Dạ anh chị dùng ngon miệng ạ. Món cuối cùng. Dạ món của anh chị đã lên đủ rồi ạ. Anh chị cần gì thêm cứ gọi em nha. Mang đồ dơ về. Trên đường quay lại quầy, tiện tay thu chén đĩa trống ở bàn đã ăn xong (hỏi khách trước nếu bàn vẫn còn ngồi). Tránh: Đặt món xuống rồi đi mà không nói gì. Hỏi cả bàn \"Món này của ai?\" — nghe kỹ bạn quầy đọc số bàn để khỏi phải hỏi. Bưng món đi ngang khách mà không chào.","h":"8a772469"},"qt4":{"so":"QT4","ten":"Gặp đâu chào đó","nhan":"","html":"<p>Mọi bạn Gặm, dù đang làm việc gì, hễ đối diện với khách là chào — không cần dừng tay, chỉ cần cúi đầu, cười, hoặc nói một câu ngắn.</p>\n<p>Quy tắc đơn giản để biết khi nào nói, khi nào chỉ cúi đầu:</p>\n<ul>\n<li><strong>Khách đang vào quán hoặc đang ra về</strong> → cúi đầu <strong>và nói</strong> câu chào.</li>\n<li><strong>Khách đang đi lại trong quán</strong> (đi vệ sinh, đi tham quan, đi ngang) → nhìn khách, cười, <strong>cúi đầu</strong> là đủ.</li>\n</ul>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Tình huống</th>\n<th>Ví dụ ở Gặm</th>\n<th>Mình làm gì</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Khách ra về, đi ngang mình</td>\n<td>Bạn tiếp thực đang bưng món vào khu E, gặp một bàn vừa ăn xong đi ra</td>\n<td>Cúi đầu, cười: <em class=\"noi\">\"Dạ Gặm cảm ơn anh chị ạ.\"</em> Vẫn bưng món tiếp, không cần dừng</td>\n</tr>\n<tr>\n<td>Khách mới bước vào, mình đang ở gần</td>\n<td>Bạn phục vụ đang dọn bàn gần cổng</td>\n<td>Cúi đầu: <em class=\"noi\">\"Dạ Gặm xin chào ạ.\"</em> Không ai ở cổng thì ra đón luôn (Quy trình 1)</td>\n</tr>\n<tr>\n<td>Khách đi vệ sinh</td>\n<td>Khách đi ngang mặt mình trên lối đi</td>\n<td>Nhìn khách, cười, cúi đầu. Khách đang tìm đường thì chỉ lối: <em class=\"noi\">\"Dạ nhà vệ sinh ở phía này ạ.\"</em></td>\n</tr>\n<tr>\n<td>Khách đi tham quan, chụp hình</td>\n<td>Khách đi xem không gian, chụp hình góc quán</td>\n<td>Cười, cúi đầu, nhường lối cho khách chụp</td>\n</tr>\n<tr>\n<td>Mình đang bưng nặng hoặc tay bận</td>\n<td>Bưng khay nhiều món, ôm chồng chén</td>\n<td>Không dừng lại, chỉ cúi đầu và nói ngắn <em class=\"noi\">\"Dạ\"</em></td>\n</tr>\n<tr>\n<td>Quản lý đi một vòng quán</td>\n<td>Quản lý đi ngang các bàn đang ăn</td>\n<td>Cúi đầu, cười với từng bàn; bàn nào nhìn lên thì hỏi: <em class=\"noi\">\"Dạ anh chị dùng món có vừa miệng không ạ?\"</em></td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Cúi đầu kiểu Gặm:</strong> đứng thẳng hoặc vừa đi vừa cúi, nhìn vào mắt khách, cười, cúi đầu nhẹ một cái. Không cần cúi sâu, quan trọng là khách thấy mình đã nhìn thấy họ.</p>","toc":[],"text":"Mọi bạn Gặm, dù đang làm việc gì, hễ đối diện với khách là chào — không cần dừng tay, chỉ cần cúi đầu, cười, hoặc nói một câu ngắn. Quy tắc đơn giản để biết khi nào nói, khi nào chỉ cúi đầu: Khách đang vào quán hoặc đang ra về → cúi đầu và nói câu chào. Khách đang đi lại trong quán (đi vệ sinh, đi tham quan, đi ngang) → nhìn khách, cười, cúi đầu là đủ. Tình huống Ví dụ ở Gặm Mình làm gì Khách ra về, đi ngang mình Bạn tiếp thực đang bưng món vào khu E, gặp một bàn vừa ăn xong đi ra Cúi đầu, cười: \"Dạ Gặm cảm ơn anh chị ạ.\" Vẫn bưng món tiếp, không cần dừng Khách mới bước vào, mình đang ở gần Bạn phục vụ đang dọn bàn gần cổng Cúi đầu: \"Dạ Gặm xin chào ạ.\" Không ai ở cổng thì ra đón luôn (Quy trình 1) Khách đi vệ sinh Khách đi ngang mặt mình trên lối đi Nhìn khách, cười, cúi đầu. Khách đang tìm đường thì chỉ lối: \"Dạ nhà vệ sinh ở phía này ạ.\" Khách đi tham quan, chụp hình Khách đi xem không gian, chụp hình góc quán Cười, cúi đầu, nhường lối cho khách chụp Mình đang bưng nặng hoặc tay bận Bưng khay nhiều món, ôm chồng chén Không dừng lại, chỉ cúi đầu và nói ngắn \"Dạ\" Quản lý đi một vòng quán Quản lý đi ngang các bàn đang ăn Cúi đầu, cười với từng bàn; bàn nào nhìn lên thì hỏi: \"Dạ anh chị dùng món có vừa miệng không ạ?\" Cúi đầu kiểu Gặm: đứng thẳng hoặc vừa đi vừa cúi, nhìn vào mắt khách, cười, cúi đầu nhẹ một cái. Không cần cúi sâu, quan trọng là khách thấy mình đã nhìn thấy họ.","h":"6c50e9d3"},"qt5":{"so":"QT5","ten":"Thanh toán","nhan":"","html":"<p>Gặm không in bill tạm tính, và bill đã in ra là không xóa món được nữa. Vì vậy luôn <strong>kiểm tra bàn trước, in bill sau</strong>.</p>\n<p class=\"lam\"><strong>Ai làm:</strong> bạn thu ngân — Gặm không có quầy thu ngân cố định; bạn thu ngân kiêm luôn order và đứng ở vị trí phía ngoài. Thu ngân đang bận thì bạn trực khu có bàn đó làm thay bước kiểm tra.</p>\n<p><strong>Khi thu ngân rảnh:</strong></p>\n<ol>\n<li><strong>Nghe khách gọi tính tiền.</strong> Đáp ngay: <em class=\"noi\">Dạ anh chị đợi em xíu ạ.</em></li>\n<li><strong>Tới tận bàn kiểm tra — chưa bấm bill.</strong> Hỏi đủ 3 điều:<ul>\n<li><strong>Món đã ra đủ chưa?</strong> Có món chưa ra mà khách không dùng nữa → báo quản lý xóa món.</li>\n<li><strong>Khách có trả lại gì không?</strong> Nước ngọt chưa khui, khăn… → mang đồ trả về và báo quản lý xóa. Ví dụ: dư 2 lon nước ngọt → đem 2 lon về, báo quản lý xóa 2 lon.</li>\n<li><strong>Có xuất hóa đơn không?</strong> <em class=\"noi\">Dạ anh chị có cần xuất hóa đơn không ạ?</em> Có → xin thông tin xuất hóa đơn của khách và lưu lại, cuối ngày quản lý xuất.</li>\n</ul>\n</li>\n<li><strong>Chờ quản lý xóa món xong</strong> (nếu có), rồi mới in bill.</li>\n<li><strong>In bill và gửi khách.</strong> <em class=\"noi\">Dạ em gửi anh chị hóa đơn ạ.</em></li>\n<li><strong>Cảm ơn.</strong> Khách thanh toán xong: <em class=\"noi\">Dạ Gặm cảm ơn anh chị ạ.</em></li>\n</ol>\n<p><strong>Khi thu ngân đang bận</strong> (đang order, đang làm với khách khác, đang hỗ trợ phục vụ):</p>\n<ol>\n<li><strong>Bạn trực khu gần nhất tới bàn.</strong> Ví dụ khách ở khu E gọi tính tiền → bạn trực khu E tới: <em class=\"noi\">Dạ anh chị đợi em xíu ạ.</em></li>\n<li><strong>Kiểm tra đủ 3 điều</strong> như bước 2 ở trên: món ra đủ chưa, có trả gì không, có xuất hóa đơn không.</li>\n<li><strong>Báo bộ đàm cho thu ngân</strong>, nói đủ số bàn + kết quả kiểm tra:<ul>\n<li>Không có gì: <em class=\"noi\">Bàn A3 tính tiền, không trả gì hết.</em> → thu ngân in bill luôn.</li>\n<li>Có đồ trả hoặc món chưa ra: <em class=\"noi\">Bàn A3 tính tiền, trả 2 lon nước ngọt.</em> → quản lý xóa món trước, thu ngân in bill sau.</li>\n<li>Có xuất hóa đơn: báo kèm <em class=\"noi\">…có xuất hóa đơn</em> và chuyển thông tin khách cho thu ngân lưu lại.</li>\n</ul>\n</li>\n</ol>\n<figure class=\"sodo\"><img alt=\"luồng thanh toán · 2 nhánh rẽ\" loading=\"lazy\" src=\"img/qt5.png\"/></figure>\n<p>Dù ai kiểm tra bàn, bill chỉ được in sau khi đã hỏi đủ 3 điều và quản lý đã xóa món cần xóa.</p>\n<div class=\"khong\"><p><strong>Tránh:</strong></p><ul>\n<li>Bấm in bill ngay khi nghe khách gọi, chưa tới bàn kiểm tra.</li>\n<li>In bill xong mới phát hiện có món chưa ra, hoặc khách trả lại nước ngọt, khăn — lúc đó không xóa được nữa.</li>\n<li>Báo bộ đàm thiếu số bàn, hoặc chỉ nói \"bàn kia tính tiền\".</li>\n</ul></div>\n","toc":[],"text":"Gặm không in bill tạm tính, và bill đã in ra là không xóa món được nữa. Vì vậy luôn kiểm tra bàn trước, in bill sau . Ai làm: bạn thu ngân — Gặm không có quầy thu ngân cố định; bạn thu ngân kiêm luôn order và đứng ở vị trí phía ngoài. Thu ngân đang bận thì bạn trực khu có bàn đó làm thay bước kiểm tra. Khi thu ngân rảnh: Nghe khách gọi tính tiền. Đáp ngay: Dạ anh chị đợi em xíu ạ. Tới tận bàn kiểm tra — chưa bấm bill. Hỏi đủ 3 điều: Món đã ra đủ chưa? Có món chưa ra mà khách không dùng nữa → báo quản lý xóa món. Khách có trả lại gì không? Nước ngọt chưa khui, khăn… → mang đồ trả về và báo quản lý xóa. Ví dụ: dư 2 lon nước ngọt → đem 2 lon về, báo quản lý xóa 2 lon. Có xuất hóa đơn không? Dạ anh chị có cần xuất hóa đơn không ạ? Có → xin thông tin xuất hóa đơn của khách và lưu lại, cuối ngày quản lý xuất. Chờ quản lý xóa món xong (nếu có), rồi mới in bill. In bill và gửi khách. Dạ em gửi anh chị hóa đơn ạ. Cảm ơn. Khách thanh toán xong: Dạ Gặm cảm ơn anh chị ạ. Khi thu ngân đang bận (đang order, đang làm với khách khác, đang hỗ trợ phục vụ): Bạn trực khu gần nhất tới bàn. Ví dụ khách ở khu E gọi tính tiền → bạn trực khu E tới: Dạ anh chị đợi em xíu ạ. Kiểm tra đủ 3 điều như bước 2 ở trên: món ra đủ chưa, có trả gì không, có xuất hóa đơn không. Báo bộ đàm cho thu ngân , nói đủ số bàn + kết quả kiểm tra: Không có gì: Bàn A3 tính tiền, không trả gì hết. → thu ngân in bill luôn. Có đồ trả hoặc món chưa ra: Bàn A3 tính tiền, trả 2 lon nước ngọt. → quản lý xóa món trước, thu ngân in bill sau. Có xuất hóa đơn: báo kèm …có xuất hóa đơn và chuyển thông tin khách cho thu ngân lưu lại. Dù ai kiểm tra bàn, bill chỉ được in sau khi đã hỏi đủ 3 điều và quản lý đã xóa món cần xóa. Tránh: Bấm in bill ngay khi nghe khách gọi, chưa tới bàn kiểm tra. In bill xong mới phát hiện có món chưa ra, hoặc khách trả lại nước ngọt, khăn — lúc đó không xóa được nữa. Báo bộ đàm thiếu số bàn, hoặc chỉ nói \"bàn kia tính tiền\".","h":"b3b20ae1"},"qt6":{"so":"QT6","ten":"Tiễn khách ra về","nhan":"","html":"<p>Không khách nào ra khỏi Gặm mà chưa nghe ít nhất một câu \"Dạ Gặm cảm ơn\" — kể cả lúc quán đông nhất.</p>\n<p><strong>Lúc bình thường – có bạn đứng cổng:</strong></p>\n<ol>\n<li>Thấy khách đi ra, bạn ở cổng quay về phía khách, cười, cúi đầu.</li>\n<li><em class=\"noi\">Dạ Gặm cảm ơn anh chị, hẹn gặp lại anh chị ạ!</em></li>\n<li>Nhìn theo khách cho tới khi khách ra khỏi cổng, không quay đi ngay.</li>\n</ol>\n<p><strong>Lúc quán đông – không có ai ở cổng:</strong> câu cảm ơn chuyển sang những người gặp khách trên đường ra.</p>\n<ol>\n<li><strong>Tại bàn.</strong> Bạn phục vụ khu đó thấy khách đứng dậy ra về thì cảm ơn ngay tại bàn: <em class=\"noi\">Dạ Gặm cảm ơn anh chị ạ.</em></li>\n<li><strong>Trên lối đi.</strong> Bạn tiếp thực, phục vụ khu khác hoặc quản lý gặp khách đang đi ra: cúi đầu, <em class=\"noi\">Dạ Gặm cảm ơn ạ.</em></li>\n<li><strong>Lúc tính tiền.</strong> Bạn thu ngân cảm ơn khi khách thanh toán xong (xem Quy trình 5): <em class=\"noi\">Dạ em cảm ơn anh chị, hẹn gặp lại anh chị ạ.</em></li>\n<li><strong>Báo quản lý.</strong> Cổng trống quá lâu thì báo quản lý để cử một bạn ra đứng khi có thể.</li>\n</ol>\n<div class=\"khong\"><p><strong>Tránh:</strong></p><ul>\n<li>Nghĩ \"cảm ơn khách là việc của bạn đứng cổng\".</li>\n<li>Thấy khách ra về mà cúi mặt làm tiếp.</li>\n</ul></div>\n","toc":[],"text":"Không khách nào ra khỏi Gặm mà chưa nghe ít nhất một câu \"Dạ Gặm cảm ơn\" — kể cả lúc quán đông nhất. Lúc bình thường – có bạn đứng cổng: Thấy khách đi ra, bạn ở cổng quay về phía khách, cười, cúi đầu. Dạ Gặm cảm ơn anh chị, hẹn gặp lại anh chị ạ! Nhìn theo khách cho tới khi khách ra khỏi cổng, không quay đi ngay. Lúc quán đông – không có ai ở cổng: câu cảm ơn chuyển sang những người gặp khách trên đường ra. Tại bàn. Bạn phục vụ khu đó thấy khách đứng dậy ra về thì cảm ơn ngay tại bàn: Dạ Gặm cảm ơn anh chị ạ. Trên lối đi. Bạn tiếp thực, phục vụ khu khác hoặc quản lý gặp khách đang đi ra: cúi đầu, Dạ Gặm cảm ơn ạ. Lúc tính tiền. Bạn thu ngân cảm ơn khi khách thanh toán xong (xem Quy trình 5): Dạ em cảm ơn anh chị, hẹn gặp lại anh chị ạ. Báo quản lý. Cổng trống quá lâu thì báo quản lý để cử một bạn ra đứng khi có thể. Tránh: Nghĩ \"cảm ơn khách là việc của bạn đứng cổng\". Thấy khách ra về mà cúi mặt làm tiếp.","h":"ff2f606a"},"thamchieu":{"so":"Bảng","ten":"Bảng tham chiếu thời gian ra món","nhan":"Bếp + Phục vụ","html":"<p>Bếp và Phục vụ cùng dùng một bảng này: món còn trong thời gian tham chiếu thì không hối bếp, chỉ báo khách thời gian dự kiến.</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Nhóm món</th>\n<th>Lúc bình thường</th>\n<th>Lúc đông (quá tải)</th>\n<th>Chủ động báo khách khi quá</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Gỏi mít – Gỏi xoài</td>\n<td>5–7 phút</td>\n<td>10–15 phút</td>\n<td>7–15 phút</td>\n</tr>\n<tr>\n<td>Gỏi bò – Gỏi chay</td>\n<td>7–10 phút</td>\n<td>10–15 phút</td>\n<td>15 phút</td>\n</tr>\n<tr>\n<td>Các món chân hấp</td>\n<td>7–10 phút</td>\n<td>10–15 phút</td>\n<td>10–15 phút</td>\n</tr>\n<tr>\n<td>Các món chân chiên</td>\n<td>7–10 phút</td>\n<td>10–15 phút</td>\n<td>10–15 phút</td>\n</tr>\n<tr>\n<td>Các món răng – sụn</td>\n<td>5–7 phút</td>\n<td>7–10 phút</td>\n<td>7–10 phút</td>\n</tr>\n<tr>\n<td>Các món vịt tiêu – cà ri</td>\n<td>7–10 phút</td>\n<td>10–15 phút</td>\n<td>10–15 phút</td>\n</tr>\n<tr>\n<td>Các món cơm – mì xào</td>\n<td>5–7 phút</td>\n<td>10–15 phút</td>\n<td>7–15 phút</td>\n</tr>\n<tr>\n<td>Các món bún</td>\n<td>7–10 phút</td>\n<td>10–15 phút</td>\n<td>15 phút</td>\n</tr>\n<tr>\n<td>Các loại mẹt</td>\n<td>10–15 phút</td>\n<td>20–25 phút</td>\n<td>25 phút</td>\n</tr>\n<tr>\n<td>Mẹt cá lóc</td>\n<td>25–30 phút</td>\n<td>30–35 phút</td>\n<td>35 phút</td>\n</tr>\n<tr>\n<td>Gà đốt Ô Thum</td>\n<td>30–35 phút</td>\n<td>35–40 phút</td>\n<td>40 phút</td>\n</tr>\n<tr>\n<td>Gà hấp mắm nhĩ</td>\n<td>30–35 phút</td>\n<td>35–40 phút</td>\n<td>40 phút</td>\n</tr>\n<tr>\n<td>Các món lẩu</td>\n<td>20–30 phút</td>\n<td>30–40 phút</td>\n<td>30 phút</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Quy định khi dùng bảng:</strong></p>\n<ul>\n<li><strong>Thời gian tính từ lúc bếp nhận bill</strong> cho tới lúc món xong, sẵn sàng giao cho phục vụ.</li>\n<li><strong>Lúc đông</strong> là khi bill dồn nhiều, nhiều bàn gọi cùng lúc, hoặc bếp đang làm nhiều món một lúc. Khi đông, Bếp báo bộ đàm ra ngoài để cả đội dùng cột \"Lúc đông\".</li>\n<li><strong>Món sắp quá thời gian:</strong> phục vụ hỏi bếp tình trạng món, rồi chủ động báo khách thời gian dự kiến, không đợi khách hỏi.</li>\n<li><strong>Chậm món, sai món hoặc món không đạt:</strong> bếp báo quản lý để xử lý kịp.</li>\n<li><strong>Gợi ý lúc order:</strong> khách gọi món lâu (gà đốt, gà hấp, mẹt cá lóc, lẩu) thì nói trước: <em class=\"noi\">Dạ món này bếp làm khoảng 30–35 phút, anh chị gọi thêm món gỏi hoặc răng sụn ăn trước trong lúc chờ nha.</em></li>\n</ul>","toc":[],"text":"Bếp và Phục vụ cùng dùng một bảng này: món còn trong thời gian tham chiếu thì không hối bếp, chỉ báo khách thời gian dự kiến. Nhóm món Lúc bình thường Lúc đông (quá tải) Chủ động báo khách khi quá Gỏi mít – Gỏi xoài 5–7 phút 10–15 phút 7–15 phút Gỏi bò – Gỏi chay 7–10 phút 10–15 phút 15 phút Các món chân hấp 7–10 phút 10–15 phút 10–15 phút Các món chân chiên 7–10 phút 10–15 phút 10–15 phút Các món răng – sụn 5–7 phút 7–10 phút 7–10 phút Các món vịt tiêu – cà ri 7–10 phút 10–15 phút 10–15 phút Các món cơm – mì xào 5–7 phút 10–15 phút 7–15 phút Các món bún 7–10 phút 10–15 phút 15 phút Các loại mẹt 10–15 phút 20–25 phút 25 phút Mẹt cá lóc 25–30 phút 30–35 phút 35 phút Gà đốt Ô Thum 30–35 phút 35–40 phút 40 phút Gà hấp mắm nhĩ 30–35 phút 35–40 phút 40 phút Các món lẩu 20–30 phút 30–40 phút 30 phút Quy định khi dùng bảng: Thời gian tính từ lúc bếp nhận bill cho tới lúc món xong, sẵn sàng giao cho phục vụ. Lúc đông là khi bill dồn nhiều, nhiều bàn gọi cùng lúc, hoặc bếp đang làm nhiều món một lúc. Khi đông, Bếp báo bộ đàm ra ngoài để cả đội dùng cột \"Lúc đông\". Món sắp quá thời gian: phục vụ hỏi bếp tình trạng món, rồi chủ động báo khách thời gian dự kiến, không đợi khách hỏi. Chậm món, sai món hoặc món không đạt: bếp báo quản lý để xử lý kịp. Gợi ý lúc order: khách gọi món lâu (gà đốt, gà hấp, mẹt cá lóc, lẩu) thì nói trước: Dạ món này bếp làm khoảng 30–35 phút, anh chị gọi thêm món gỏi hoặc răng sụn ăn trước trong lúc chờ nha.","h":"cb36ec17"},"qt7":{"so":"QT7","ten":"Khi món ra trễ (Bếp – Phục vụ phối hợp)","nhan":"","html":"<p>Thấy sớm – báo đúng người – xử lý đúng chỗ. Không để khách phải hỏi món lần thứ hai.</p>\n<p class=\"lam\"><strong>Ai làm gì:</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Ai</th>\n<th>Việc của mình</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Phục vụ phụ trách bàn</td>\n<td>Kiểm tra giờ order, báo khách thời gian dự kiến, bộ đàm báo Bếp khi quá mốc, theo sát bàn đang trễ, báo anh Sơn nếu vẫn chưa ra</td>\n</tr>\n<tr>\n<td>Bếp</td>\n<td>Ưu tiên ngay món đang trễ khi được nhắc; chủ động bộ đàm ra ngoài khi bếp gặp sự cố</td>\n</tr>\n<tr>\n<td>Anh Sơn (quản lý)</td>\n<td>Vào bếp nhắc đúng người phụ trách món đó, không nhắc chung cả bếp</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Mốc chủ động xử lý</strong> (tính từ thời gian tham chiếu của món, áp dụng cả lúc bình thường và lúc đông):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Loại món</th>\n<th>Quá thời gian tham chiếu</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Món lẻ</td>\n<td>khoảng 5 phút</td>\n</tr>\n<tr>\n<td>Món chính</td>\n<td>khoảng 10 phút</td>\n</tr>\n</tbody>\n</table></div>\n<p>Tới mốc này món thực tế có thể đã trễ 10–20 phút, nên phải xử lý ngay.</p>\n<p><strong>Các bước xử lý:</strong></p>\n<ol>\n<li><strong>Khách hỏi món, hoặc bàn còn 1–2 món chưa ra.</strong> Phục vụ mở điện thoại xem giờ order món đó, so với bảng thời gian tham chiếu. Nói với khách trước: <em class=\"noi\">Dạ em xin lỗi mình nha, để em kiểm tra món này liền cho mình.</em></li>\n<li><strong>Chưa tới mốc</strong> → giải thích thời gian dự kiến theo bảng tham chiếu: <em class=\"noi\">Dạ món của mình đang làm, khoảng ___ phút nữa sẽ lên nha.</em></li>\n<li><strong>Đã quá mốc</strong> → bộ đàm báo Bếp, nói đủ 4 ý: <strong>bàn nào · món gì · order bao lâu · đang trễ</strong>. Ví dụ: <em class=\"noi\">Bếp ơi, bàn B1 món gà đốt, order 35 phút rồi, đang trễ.</em></li>\n<li><strong>Quay lại báo khách.</strong> Có giờ chính xác từ Bếp: <em class=\"noi\">Dạ em coi rồi, món mình đang làm, khoảng ___ phút nữa sẽ lên. Em đã nhờ bếp làm trước món này rồi nha.</em> Chưa biết chính xác: <em class=\"noi\">Dạ em đang kiểm tra lại với bếp. Cho em 2 phút em quay lại báo mình chính xác nha.</em></li>\n<li><strong>Theo sát bàn đó.</strong> Bạn phục vụ bàn đó để mắt nhiều hơn tới món đang trễ, chủ động cập nhật cho khách trước khi khách phải hỏi lại.</li>\n<li><strong>Vẫn chưa ra</strong> → báo anh Sơn. Anh Sơn vào bếp nhắc đúng bạn phụ trách món đó (bàn B1 chờ gà đốt → tìm đúng bạn phụ trách món gà), để các bạn khác vẫn tập trung làm món.</li>\n<li><strong>Bếp ưu tiên ngay món đang trễ</strong>, giải quyết dứt điểm phần còn thiếu của bàn. Món lên → làm theo Quy trình 3, kèm một câu: <em class=\"noi\">Dạ em xin lỗi để mình chờ lâu, món của mình đây ạ.</em></li>\n<li><strong>Khách không muốn chờ nữa hoặc rất bực</strong> → không giải thích thêm, báo anh Sơn xuống hỗ trợ: <em class=\"noi\">Dạ em xin lỗi để mình chờ lâu. Để em báo quản lý xử lý phần món này cho mình liền ạ</em></li>\n</ol>\n<figure class=\"sodo\"><img alt=\"luồng xử lý món ra trễ · 2 mốc báo\" loading=\"lazy\" src=\"img/qt7.png\"/></figure>\n<p>Mỗi lần báo là một nấc: quá mốc thì báo Bếp, đã báo Bếp mà vẫn chưa ra thì báo anh Sơn.</p>\n<p><strong>Khi Bếp gặp sực cố</strong> (hết gas, quá tải dồn một khâu, thiết bị hư, món phải làm lại, order tăng đột biến):</p>\n<ul>\n<li>Bếp chủ động bộ đàm ra ngoài: món nào, đang gặp chuyện gì. Ví dụ: <em class=\"noi\">Bếp báo: món gà đốt đang dồn, ra chậm.</em></li>\n<li>Phục vụ nắm trước thì nói trước với khách lúc order, và gợi ý món khác nếu phù hợp — thay vì để khách chờ lâu rồi mới xử lý.</li>\n</ul>\n<p><strong>Thời gian tham chiếu không phải luật cứng.</strong> Mốc thời gian là để mình chủ động theo dõi và phối hợp, không phải để Bếp và Phục vụ quy trách nhiệm cho nhau. Bếp báo thông tin để Phục vụ chủ động với khách; Phục vụ nhắc đúng lúc để Bếp không sót món; anh Sơn xử lý khi đã trễ và cần can thiệp trực tiếp.</p>\n<div class=\"khong\"><p><strong>Tránh:</strong></p><ul>\n<li>Để khách hỏi món lần hai, lần ba mới bắt đầu xử lý.</li>\n<li>Bộ đàm thiếu bàn hoặc thiếu tên món (\"bếp ơi món bàn kia đâu rồi\").</li>\n<li>Nói đại với khách \"sắp có rồi\" khi chưa hỏi Bếp.</li>\n<li>Nhắc chung cả bếp, hoặc đổ lỗi qua lại giữa Bếp và Phục vụ.</li>\n</ul></div>\n\n<p><a href=\"#qt/b/thamchieu\">→ Xem Bảng tham chiếu thời gian ra món</a></p>","toc":[],"text":"Thấy sớm – báo đúng người – xử lý đúng chỗ. Không để khách phải hỏi món lần thứ hai. Ai làm gì: Ai Việc của mình Phục vụ phụ trách bàn Kiểm tra giờ order, báo khách thời gian dự kiến, bộ đàm báo Bếp khi quá mốc, theo sát bàn đang trễ, báo anh Sơn nếu vẫn chưa ra Bếp Ưu tiên ngay món đang trễ khi được nhắc; chủ động bộ đàm ra ngoài khi bếp gặp sự cố Anh Sơn (quản lý) Vào bếp nhắc đúng người phụ trách món đó, không nhắc chung cả bếp Mốc chủ động xử lý (tính từ thời gian tham chiếu của món, áp dụng cả lúc bình thường và lúc đông): Loại món Quá thời gian tham chiếu Món lẻ khoảng 5 phút Món chính khoảng 10 phút Tới mốc này món thực tế có thể đã trễ 10–20 phút, nên phải xử lý ngay. Các bước xử lý: Khách hỏi món, hoặc bàn còn 1–2 món chưa ra. Phục vụ mở điện thoại xem giờ order món đó, so với bảng thời gian tham chiếu. Nói với khách trước: Dạ em xin lỗi mình nha, để em kiểm tra món này liền cho mình. Chưa tới mốc → giải thích thời gian dự kiến theo bảng tham chiếu: Dạ món của mình đang làm, khoảng ___ phút nữa sẽ lên nha. Đã quá mốc → bộ đàm báo Bếp, nói đủ 4 ý: bàn nào · món gì · order bao lâu · đang trễ . Ví dụ: Bếp ơi, bàn B1 món gà đốt, order 35 phút rồi, đang trễ. Quay lại báo khách. Có giờ chính xác từ Bếp: Dạ em coi rồi, món mình đang làm, khoảng ___ phút nữa sẽ lên. Em đã nhờ bếp làm trước món này rồi nha. Chưa biết chính xác: Dạ em đang kiểm tra lại với bếp. Cho em 2 phút em quay lại báo mình chính xác nha. Theo sát bàn đó. Bạn phục vụ bàn đó để mắt nhiều hơn tới món đang trễ, chủ động cập nhật cho khách trước khi khách phải hỏi lại. Vẫn chưa ra → báo anh Sơn. Anh Sơn vào bếp nhắc đúng bạn phụ trách món đó (bàn B1 chờ gà đốt → tìm đúng bạn phụ trách món gà), để các bạn khác vẫn tập trung làm món. Bếp ưu tiên ngay món đang trễ , giải quyết dứt điểm phần còn thiếu của bàn. Món lên → làm theo Quy trình 3, kèm một câu: Dạ em xin lỗi để mình chờ lâu, món của mình đây ạ. Khách không muốn chờ nữa hoặc rất bực → không giải thích thêm, báo anh Sơn xuống hỗ trợ: Dạ em xin lỗi để mình chờ lâu. Để em báo quản lý xử lý phần món này cho mình liền ạ Mỗi lần báo là một nấc: quá mốc thì báo Bếp, đã báo Bếp mà vẫn chưa ra thì báo anh Sơn. Khi Bếp gặp sực cố (hết gas, quá tải dồn một khâu, thiết bị hư, món phải làm lại, order tăng đột biến): Bếp chủ động bộ đàm ra ngoài: món nào, đang gặp chuyện gì. Ví dụ: Bếp báo: món gà đốt đang dồn, ra chậm. Phục vụ nắm trước thì nói trước với khách lúc order, và gợi ý món khác nếu phù hợp — thay vì để khách chờ lâu rồi mới xử lý. Thời gian tham chiếu không phải luật cứng. Mốc thời gian là để mình chủ động theo dõi và phối hợp, không phải để Bếp và Phục vụ quy trách nhiệm cho nhau. Bếp báo thông tin để Phục vụ chủ động với khách; Phục vụ nhắc đúng lúc để Bếp không sót món; anh Sơn xử lý khi đã trễ và cần can thiệp trực tiếp. Tránh: Để khách hỏi món lần hai, lần ba mới bắt đầu xử lý. Bộ đàm thiếu bàn hoặc thiếu tên món (\"bếp ơi món bàn kia đâu rồi\"). Nói đại với khách \"sắp có rồi\" khi chưa hỏi Bếp. Nhắc chung cả bếp, hoặc đổ lỗi qua lại giữa Bếp và Phục vụ. → Xem Bảng tham chiếu thời gian ra món","h":"12c48ced"},"qt9":{"so":"QT9","ten":"Sắp xếp bàn đặt buổi chiều","nhan":"","html":"<p>Đúng 4 giờ chiều, mọi bàn đặt tối nay phải được xếp chỗ xong, để khách tới là có bàn đúng khu, đủ ghế, không phải chờ ghép.</p>\n<p class=\"lam\"><strong>Ai làm:</strong> quản lý hoặc bạn thu ngân.</p>\n<p><strong>Các bước lúc 4 giờ chiều:</strong></p>\n<ol>\n<li><strong>Check Zalo.</strong> Mở Zalo, xem hết tin đặt bàn và đơn đặt hàng cho tối nay. Ghi lại từng bàn: tên khách, số điện thoại, giờ tới, số người, ghi chú (sinh nhật, có trẻ nhỏ…).</li>\n<li><strong>Chia khu theo số người:</strong><ul>\n<li>Khách đi lẻ, khoảng 4 người trở xuống → khu phụ xe.</li>\n<li>Khách đặt trên 4 người → khu B.</li>\n</ul>\n</li>\n<li><strong>Tính số bàn cần ghép</strong> theo bảng dưới, rồi ghép bàn và xếp ghế sẵn.</li>\n<li><strong>Báo cả đội.</strong> Nói cho phục vụ từng khu biết bàn nào đã đặt, mấy giờ, bao nhiêu người.</li>\n<li><strong>Khách đặt tới:</strong> đối chiếu tên hoặc số điện thoại, dẫn thẳng tới bàn (Quy trình 1).</li>\n</ol>\n<p><strong>Cách tính số bàn:</strong></p>\n<ul>\n<li><strong>Dưới 10 người:</strong> 1 bàn tính 4 người.</li>\n<li><strong>Từ 10 người trở lên:</strong> 1 bàn tính 3 người. Ví dụ: 15 người = 5 bàn ghép.</li>\n<li>Lẻ người thì thêm 1 bàn.</li>\n</ul>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Số khách</th>\n<th>Số bàn ghép</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1–4</td>\n<td>1</td>\n</tr>\n<tr>\n<td>5–8</td>\n<td>2</td>\n</tr>\n<tr>\n<td>9</td>\n<td>3</td>\n</tr>\n<tr>\n<td>10–12</td>\n<td>4</td>\n</tr>\n<tr>\n<td>13–15</td>\n<td>5</td>\n</tr>\n<tr>\n<td>16–18</td>\n<td>6</td>\n</tr>\n<tr>\n<td>19–21</td>\n<td>7</td>\n</tr>\n<tr>\n<td>22–24</td>\n<td>8</td>\n</tr>\n<tr>\n<td>25–27</td>\n<td>9</td>\n</tr>\n<tr>\n<td>28–30</td>\n<td>10</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"m1\">Khi khách vãng lai muốn ngồi bàn đã có người đặt</h3>\n<p>Ví dụ: bàn đã đặt lúc 7 giờ tối, 6 giờ có khách tới muốn ngồi bàn đó. Khách được ngồi nếu đồng ý thanh toán trước giờ đặt 15 phút (6 giờ 45). Phải nói rõ <strong>trước khi khách ngồi</strong>, không đợi ngồi rồi mới nói.</p>\n<ol>\n<li><strong>Mời khách, nói rõ giờ:</strong> <em class=\"noi\">Dạ anh chị ơi, bàn này Gặm đã nhận đặt cho khách lúc 7 giờ. Nếu anh chị dùng bữa trong khoảng 45 phút thì em mời anh chị ngồi đây luôn, em nhờ anh chị thanh toán giúp em trước 6 giờ 45 để Gặm kịp dọn bàn đón khách nha. Anh chị thấy được không ạ?</em></li>\n<li><strong>Nếu còn bàn khác, cho khách chọn:</strong> <em class=\"noi\">Còn nếu anh chị muốn ngồi thong thả, em xếp cho mình bàn bên ___ nha.</em></li>\n<li><strong>Khách đồng ý:</strong> order nhanh, báo bếp bàn này cần ra món sớm.</li>\n<li><strong>Khoảng 6 giờ 30, nhắc nhẹ:</strong> <em class=\"noi\">Dạ anh chị ơi, em nhắc nhẹ là khoảng 15 phút nữa bàn mình có khách đặt tới. Anh chị cần gọi thêm gì thì em lấy luôn một lượt nha.</em></li>\n<li><strong>6 giờ 45, gửi hóa đơn</strong> (theo Quy trình 5): <em class=\"noi\">Dạ em gửi anh chị hóa đơn ạ. Cảm ơn anh chị đã thông cảm cho Gặm nha.</em></li>\n<li><strong>Tới giờ mà khách chưa xong</strong>, khách đặt đã tới: báo quản lý. Quản lý mời khách đặt ngồi chờ hoặc xếp bàn khác, không giục khách đang ăn đứng dậy.</li>\n</ol>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Bàn này có người đặt rồi, anh chị ngồi tạm thôi.\" · \"Tới giờ rồi, anh chị đứng lên giúp em.\"</p></div>","toc":["Khi khách vãng lai muốn ngồi bàn đã có người đặt"],"text":"Đúng 4 giờ chiều, mọi bàn đặt tối nay phải được xếp chỗ xong, để khách tới là có bàn đúng khu, đủ ghế, không phải chờ ghép. Ai làm: quản lý hoặc bạn thu ngân. Các bước lúc 4 giờ chiều: Check Zalo. Mở Zalo, xem hết tin đặt bàn và đơn đặt hàng cho tối nay. Ghi lại từng bàn: tên khách, số điện thoại, giờ tới, số người, ghi chú (sinh nhật, có trẻ nhỏ…). Chia khu theo số người: Khách đi lẻ, khoảng 4 người trở xuống → khu phụ xe. Khách đặt trên 4 người → khu B. Tính số bàn cần ghép theo bảng dưới, rồi ghép bàn và xếp ghế sẵn. Báo cả đội. Nói cho phục vụ từng khu biết bàn nào đã đặt, mấy giờ, bao nhiêu người. Khách đặt tới: đối chiếu tên hoặc số điện thoại, dẫn thẳng tới bàn (Quy trình 1). Cách tính số bàn: Dưới 10 người: 1 bàn tính 4 người. Từ 10 người trở lên: 1 bàn tính 3 người. Ví dụ: 15 người = 5 bàn ghép. Lẻ người thì thêm 1 bàn. Số khách Số bàn ghép 1–4 1 5–8 2 9 3 10–12 4 13–15 5 16–18 6 19–21 7 22–24 8 25–27 9 28–30 10 Khi khách vãng lai muốn ngồi bàn đã có người đặt Ví dụ: bàn đã đặt lúc 7 giờ tối, 6 giờ có khách tới muốn ngồi bàn đó. Khách được ngồi nếu đồng ý thanh toán trước giờ đặt 15 phút (6 giờ 45). Phải nói rõ trước khi khách ngồi , không đợi ngồi rồi mới nói. Mời khách, nói rõ giờ: Dạ anh chị ơi, bàn này Gặm đã nhận đặt cho khách lúc 7 giờ. Nếu anh chị dùng bữa trong khoảng 45 phút thì em mời anh chị ngồi đây luôn, em nhờ anh chị thanh toán giúp em trước 6 giờ 45 để Gặm kịp dọn bàn đón khách nha. Anh chị thấy được không ạ? Nếu còn bàn khác, cho khách chọn: Còn nếu anh chị muốn ngồi thong thả, em xếp cho mình bàn bên ___ nha. Khách đồng ý: order nhanh, báo bếp bàn này cần ra món sớm. Khoảng 6 giờ 30, nhắc nhẹ: Dạ anh chị ơi, em nhắc nhẹ là khoảng 15 phút nữa bàn mình có khách đặt tới. Anh chị cần gọi thêm gì thì em lấy luôn một lượt nha. 6 giờ 45, gửi hóa đơn (theo Quy trình 5): Dạ em gửi anh chị hóa đơn ạ. Cảm ơn anh chị đã thông cảm cho Gặm nha. Tới giờ mà khách chưa xong , khách đặt đã tới: báo quản lý. Quản lý mời khách đặt ngồi chờ hoặc xếp bàn khác, không giục khách đang ăn đứng dậy. Không nói: \"Bàn này có người đặt rồi, anh chị ngồi tạm thôi.\" · \"Tới giờ rồi, anh chị đứng lên giúp em.\"","h":"fd61973a"},"caunoi":{"so":"“”","ten":"Bảng câu nói chuẩn của Gặm","nhan":"","html":"<p>In bảng này dán ở khu nhân viên để bạn mới học thuộc trong tuần đầu.</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Lúc nào</th>\n<th>Câu nói</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Khách tới cổng</td>\n<td>Dạ Gặm xin chào anh chị ạ!</td>\n</tr>\n<tr>\n<td>Hỏi số người</td>\n<td>Dạ anh chị mình đi mấy người ạ?</td>\n</tr>\n<tr>\n<td>Hỏi đặt bàn</td>\n<td>Dạ anh chị mình có đặt bàn trước chưa ạ?</td>\n</tr>\n<tr>\n<td>Dẫn bàn</td>\n<td>Dạ mời anh chị đi lối này ạ. / Dạ anh chị ngồi bàn này nha.</td>\n</tr>\n<tr>\n<td>Gửi menu</td>\n<td>Dạ em gửi anh chị menu ạ.</td>\n</tr>\n<tr>\n<td>Khách giơ tay</td>\n<td>Dạ anh chị đã chọn được món chưa ạ?</td>\n</tr>\n<tr>\n<td>Khách chưa chọn được sau 4–5 phút</td>\n<td>Dạ anh chị có cần em tư vấn gì không ạ? Những món có đánh dấu ngôi sao là món khách thích ăn nhất ở Gặm đó ạ.</td>\n</tr>\n<tr>\n<td>Đọc lại order</td>\n<td>Dạ em xin đọc lại món của anh chị ạ…</td>\n</tr>\n<tr>\n<td>Lên món</td>\n<td>Dạ em xin phép lên món ạ. Đây là món ___ của anh chị ạ.</td>\n</tr>\n<tr>\n<td>Lên đủ món</td>\n<td>Dạ món của anh chị đã lên đủ rồi ạ. Anh chị cần gì thêm cứ gọi em nha.</td>\n</tr>\n<tr>\n<td>Khách gọi tính tiền</td>\n<td>Dạ anh chị đợi em xíu ạ.</td>\n</tr>\n<tr>\n<td>Kiểm tra bàn trước khi in bill</td>\n<td>Dạ món của anh chị đã ra đủ chưa ạ? Anh chị có trả lại nước hay khăn gì không ạ? Anh chị có cần xuất hóa đơn không ạ?</td>\n</tr>\n<tr>\n<td>Báo bộ đàm cho thu ngân</td>\n<td>Bàn A3 tính tiền, không trả gì hết. / Bàn A3 tính tiền, trả 2 lon nước ngọt.</td>\n</tr>\n<tr>\n<td>Gửi bill</td>\n<td>Dạ em gửi anh chị hóa đơn ạ.</td>\n</tr>\n<tr>\n<td>Khách ra về</td>\n<td>Dạ Gặm cảm ơn anh chị, hẹn gặp lại anh chị ạ!</td>\n</tr>\n<tr>\n<td>Khách đi ngang trong quán</td>\n<td>(Cười + cúi đầu, không cần nói)</td>\n</tr>\n</tbody>\n</table></div>","toc":[],"text":"In bảng này dán ở khu nhân viên để bạn mới học thuộc trong tuần đầu. Lúc nào Câu nói Khách tới cổng Dạ Gặm xin chào anh chị ạ! Hỏi số người Dạ anh chị mình đi mấy người ạ? Hỏi đặt bàn Dạ anh chị mình có đặt bàn trước chưa ạ? Dẫn bàn Dạ mời anh chị đi lối này ạ. / Dạ anh chị ngồi bàn này nha. Gửi menu Dạ em gửi anh chị menu ạ. Khách giơ tay Dạ anh chị đã chọn được món chưa ạ? Khách chưa chọn được sau 4–5 phút Dạ anh chị có cần em tư vấn gì không ạ? Những món có đánh dấu ngôi sao là món khách thích ăn nhất ở Gặm đó ạ. Đọc lại order Dạ em xin đọc lại món của anh chị ạ… Lên món Dạ em xin phép lên món ạ. Đây là món ___ của anh chị ạ. Lên đủ món Dạ món của anh chị đã lên đủ rồi ạ. Anh chị cần gì thêm cứ gọi em nha. Khách gọi tính tiền Dạ anh chị đợi em xíu ạ. Kiểm tra bàn trước khi in bill Dạ món của anh chị đã ra đủ chưa ạ? Anh chị có trả lại nước hay khăn gì không ạ? Anh chị có cần xuất hóa đơn không ạ? Báo bộ đàm cho thu ngân Bàn A3 tính tiền, không trả gì hết. / Bàn A3 tính tiền, trả 2 lon nước ngọt. Gửi bill Dạ em gửi anh chị hóa đơn ạ. Khách ra về Dạ Gặm cảm ơn anh chị, hẹn gặp lại anh chị ạ! Khách đi ngang trong quán (Cười + cúi đầu, không cần nói)","h":"a0475647"},"checklist":{"so":"✓","ten":"Checklist quản lý mỗi ca","nhan":"Quản lý","html":"<p>Lịch đứng vị trí cả tuần quản lý đã xếp từ cuối tuần trước, nên checklist này chỉ gồm những việc cần kiểm tra trong từng ca.</p>\n<p><strong>Đầu ca chiều (quản lý và thu ngân)</strong></p>\n<ul>\n<li class=\"chk\">Tối nay có bao nhiêu bàn đặt, đã xếp chỗ xong chưa (Quy trình 9).</li>\n<li class=\"chk\">Hỏi bếp có món nào hết hoặc sắp hết, báo cho cả đội phục vụ biết.</li>\n<li class=\"chk\">Nhắc phục vụ đi một vòng kiểm tra đã chuẩn bị lên hết chưa.</li>\n<li class=\"chk\">Quản lý kiểm tra nhà vệ sinh và các khu đã dọn dẹp xong chưa.</li>\n</ul>\n<p><strong>Trong ca</strong></p>\n<ul>\n<li class=\"chk\">Đi một vòng: có bàn nào ngồi quá 5 phút có menu mà chưa ai tới hỏi không?</li>\n<li class=\"chk\">Có bàn nào order xong 5–10 phút mà chưa có món nào ra không? (xử lý theo Quy trình 7)</li>\n<li class=\"chk\">Khách ra về có ai cảm ơn không, nhất là lúc cổng trống?</li>\n<li class=\"chk\">Tiếp thực có nhận món ở quầy và báo tên món khi lên món không?</li>\n</ul>\n<p><strong>Cuối ca</strong></p>\n<ul>\n<li class=\"chk\">Xuất các hóa đơn đã lưu thông tin khách trong ngày.</li>\n<li class=\"chk\">Khen 1 bạn làm tốt (nêu tình huống cụ thể).</li>\n<li class=\"chk\">Nhắc 1 điểm cần sửa, đưa vào buổi họp thứ Hai nếu lặp lại nhiều lần.</li>\n</ul>","toc":[],"text":"Lịch đứng vị trí cả tuần quản lý đã xếp từ cuối tuần trước, nên checklist này chỉ gồm những việc cần kiểm tra trong từng ca. Đầu ca chiều (quản lý và thu ngân) Tối nay có bao nhiêu bàn đặt, đã xếp chỗ xong chưa (Quy trình 9). Hỏi bếp có món nào hết hoặc sắp hết, báo cho cả đội phục vụ biết. Nhắc phục vụ đi một vòng kiểm tra đã chuẩn bị lên hết chưa. Quản lý kiểm tra nhà vệ sinh và các khu đã dọn dẹp xong chưa. Trong ca Đi một vòng: có bàn nào ngồi quá 5 phút có menu mà chưa ai tới hỏi không? Có bàn nào order xong 5–10 phút mà chưa có món nào ra không? (xử lý theo Quy trình 7) Khách ra về có ai cảm ơn không, nhất là lúc cổng trống? Tiếp thực có nhận món ở quầy và báo tên món khi lên món không? Cuối ca Xuất các hóa đơn đã lưu thông tin khách trong ngày. Khen 1 bạn làm tốt (nêu tình huống cụ thể). Nhắc 1 điểm cần sửa, đưa vào buổi họp thứ Hai nếu lặp lại nhiều lần.","h":"9c28081f"},"quay1":{"so":"1","ten":"Đầu ca – nhận quầy","nhan":"","html":"<p>Quầy chuẩn bị đủ từ đầu ca thì cả ca không ai phải chạy đi châm, đi cắt giữa giờ bán. Quầy cũng là chỗ kiểm tra cuối cùng trước khi món ra tới khách.</p>\n<p class=\"lam\"><strong>Ai làm:</strong> bạn đứng quầy ca 1 (ca sáng) và ca 2 (ca chiều – tối). Trong giờ bán, quầy có 2 bạn: một bạn ra chân gà và món nước, một bạn lấy món từ bếp và đọc bàn cho tiếp thực (xem Quy trình 3).</p>\n<p><strong>Vệ sinh (cả ca 1 và ca 2):</strong></p>\n<ul>\n<li class=\"chk\">Quét, lau quầy — đặc biệt các hũ trên quầy, laptop, đầu amply.</li>\n<li class=\"chk\">Quét, lau lại sàn quầy cho sạch.</li>\n</ul>\n<p><strong>Lịch vệ sinh hằng tuần (ca sáng làm):</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Ngày</th>\n<th>Việc</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Thứ Hai</td>\n<td>Chà kệ để ly, tránh cặn canxi đóng dơ kệ</td>\n</tr>\n<tr>\n<td>Thứ Ba và thứ Bảy</td>\n<td>Vệ sinh 2 tủ lạnh trong quầy, sắp xếp hàng bán gọn gàng</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Hàng bán – phải đủ cho cả ngày:</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Hạng mục</th>\n<th>Kiểm tra</th>\n<th>Thiếu thì làm gì</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Chân gà</td>\n<td>Đủ bán theo số lượng bán hằng ngày ghi đầu sổ</td>\n<td>Làm phiếu xuất để bếp xuất lên</td>\n</tr>\n<tr>\n<td>Nước chấm</td>\n<td>Nước tương, mắm nêm, mắm gừng, mắm mặn, mắm chua ngọt, mắm gỏi mít, chao chấm, nước tương bún xì dầu</td>\n<td>Loại có sẵn thì tự châm lên; loại cần pha thì báo bếp pha</td>\n</tr>\n<tr>\n<td>Phụ liệu</td>\n<td>Lá chanh, ớt cắt, tắc cắt lát, tắc cắt đầu, thơm bằm, lá dứa, xoài cóc</td>\n<td>Ca sáng: bào, cắt liền. Ca chiều: báo quản lý</td>\n</tr>\n<tr>\n<td>Nước bán</td>\n<td>Đủ cho tới hết ca tối</td>\n<td>Báo quản lý để bổ sung</td>\n</tr>\n<tr>\n<td>Trà</td>\n<td>Nấu đầu ngày</td>\n<td>Không nấu vào cuối ca sáng — ủ không tới, trà không nguội kịp để bảo quản</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Định lượng chuẩn bị buổi sáng:</strong> chuẩn bị đúng số lượng này, không làm dư để khỏi hư và bỏ.</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Hạng mục</th>\n<th>Trong tuần (Thứ Hai – Thứ Năm)</th>\n<th>Cuối tuần (Thứ Sáu – Chủ Nhật)</th>\n<th>Ghi chú</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Xoài cóc đã gọt</td>\n<td>2 kg</td>\n<td>3 kg</td>\n<td>Tổng cả ngày</td>\n</tr>\n<tr>\n<td>Ớt cắt</td>\n<td>1 hộp canh súp</td>\n<td>1 hôp hấp</td>\n<td></td>\n</tr>\n<tr>\n<td>Tắc cắt lát</td>\n<td>2/3 hộp hấp</td>\n<td>1 hộp hấp</td>\n<td></td>\n</tr>\n<tr>\n<td>Lá chanh cắt sẵn</td>\n<td>Khoảng 2/3 hộp thiếc</td>\n<td>Khoảng 2/3 hộp thiếc</td>\n<td><strong>Không cắt buổi sáng</strong> — khoảng 2–3 giờ chiều mới cắt</td>\n</tr>\n<tr>\n<td>Nước sả chanh</td>\n<td>Xả tối đa 3 chai</td>\n<td>Xả tối đa 3 chai</td>\n<td>Xả đầu ngày</td>\n</tr>\n<tr>\n<td>Sâm, thốt nốt, trà tắc</td>\n<td>Xả 4 chai mỗi loại</td>\n<td>Xả 5 chai mỗi loại</td>\n<td>Xả đầu ngày</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Ca sáng và ca chiều làm khác nhau:</strong></p>\n<ul>\n<li><strong>Ca sáng:</strong> kiểm tra từng món, thiếu là làm liền. Cử một bạn ra chuẩn bị trước, làm thứ bán nhiều và thứ lâu mới xong trước.</li>\n<li><strong>Ca chiều:</strong> kiểm tra mọi thứ đã được châm chưa. Chưa thì báo quản lý liền, quản lý xem tình hình bán trong ngày rồi quyết. <strong>Không báo mà trong ca thiếu hàng bán thì bạn đứng quầy ca chiều chịu trách nhiệm</strong>, không đổ lỗi cho ca sáng.</li>\n</ul>","toc":[],"text":"Quầy chuẩn bị đủ từ đầu ca thì cả ca không ai phải chạy đi châm, đi cắt giữa giờ bán. Quầy cũng là chỗ kiểm tra cuối cùng trước khi món ra tới khách. Ai làm: bạn đứng quầy ca 1 (ca sáng) và ca 2 (ca chiều – tối). Trong giờ bán, quầy có 2 bạn: một bạn ra chân gà và món nước, một bạn lấy món từ bếp và đọc bàn cho tiếp thực (xem Quy trình 3). Vệ sinh (cả ca 1 và ca 2): Quét, lau quầy — đặc biệt các hũ trên quầy, laptop, đầu amply. Quét, lau lại sàn quầy cho sạch. Lịch vệ sinh hằng tuần (ca sáng làm): Ngày Việc Thứ Hai Chà kệ để ly, tránh cặn canxi đóng dơ kệ Thứ Ba và thứ Bảy Vệ sinh 2 tủ lạnh trong quầy, sắp xếp hàng bán gọn gàng Hàng bán – phải đủ cho cả ngày: Hạng mục Kiểm tra Thiếu thì làm gì Chân gà Đủ bán theo số lượng bán hằng ngày ghi đầu sổ Làm phiếu xuất để bếp xuất lên Nước chấm Nước tương, mắm nêm, mắm gừng, mắm mặn, mắm chua ngọt, mắm gỏi mít, chao chấm, nước tương bún xì dầu Loại có sẵn thì tự châm lên; loại cần pha thì báo bếp pha Phụ liệu Lá chanh, ớt cắt, tắc cắt lát, tắc cắt đầu, thơm bằm, lá dứa, xoài cóc Ca sáng: bào, cắt liền. Ca chiều: báo quản lý Nước bán Đủ cho tới hết ca tối Báo quản lý để bổ sung Trà Nấu đầu ngày Không nấu vào cuối ca sáng — ủ không tới, trà không nguội kịp để bảo quản Định lượng chuẩn bị buổi sáng: chuẩn bị đúng số lượng này, không làm dư để khỏi hư và bỏ. Hạng mục Trong tuần (Thứ Hai – Thứ Năm) Cuối tuần (Thứ Sáu – Chủ Nhật) Ghi chú Xoài cóc đã gọt 2 kg 3 kg Tổng cả ngày Ớt cắt 1 hộp canh súp 1 hôp hấp Tắc cắt lát 2/3 hộp hấp 1 hộp hấp Lá chanh cắt sẵn Khoảng 2/3 hộp thiếc Khoảng 2/3 hộp thiếc Không cắt buổi sáng — khoảng 2–3 giờ chiều mới cắt Nước sả chanh Xả tối đa 3 chai Xả tối đa 3 chai Xả đầu ngày Sâm, thốt nốt, trà tắc Xả 4 chai mỗi loại Xả 5 chai mỗi loại Xả đầu ngày Ca sáng và ca chiều làm khác nhau: Ca sáng: kiểm tra từng món, thiếu là làm liền. Cử một bạn ra chuẩn bị trước, làm thứ bán nhiều và thứ lâu mới xong trước. Ca chiều: kiểm tra mọi thứ đã được châm chưa. Chưa thì báo quản lý liền, quản lý xem tình hình bán trong ngày rồi quyết. Không báo mà trong ca thiếu hàng bán thì bạn đứng quầy ca chiều chịu trách nhiệm , không đổ lỗi cho ca sáng.","h":"df5c0740"},"quay2":{"so":"2","ten":"Trong ca – ra món","nhan":"","html":"<ol>\n<li><strong>Thử chất lượng trước khi ra chân gà hoặc món nước.</strong> Mỗi bịch chân gà đổ ra thùng để bán, bạn ra món dùng muỗng múc 1 chiếc ăn thử xem có bị lên men hay có mùi lạ không. <strong>Bịch nào cũng phải thử.</strong> Nước nấu cũng thử trước khi làm món. Có vấn đề thì ngưng ra món, báo quản lý ngay.</li>\n<li><strong>Kiểm tra món trước khi đọc bàn.</strong> Đủ nước chấm, ớt, kẹo, bánh tráng, bánh đa cho những món cần có.</li>\n<li><strong>Đọc bàn cho tiếp thực.</strong> Đọc rõ <strong>số bàn + tên món</strong>, chờ tiếp thực lặp lại rồi mới giao món.</li>\n<li><strong>Đơn app và đơn mang về.</strong> Đủ muỗng đũa, nước chấm, bánh đa, bánh tráng; đối chiếu với hóa đơn một lần cuối rồi mới đưa tài xế.</li>\n<li><strong>Rửa ly đúng cách.</strong> Lật đáy ly lên, dùng bàn chải chà đáy vì ly của quán dễ đóng cặn dơ dưới đáy. Thấy đáy ly đóng cặn đen thì báo quản lý liền.</li>\n<li><strong>Sắp hết hàng giữa ca</strong> (nước chấm, phụ liệu, nước bán) → báo bộ đàm cho quản lý và phục vụ biết trước, đừng đợi hết hẳn mới nói.</li>\n<li><strong>Giữ quầy yên.</strong> Không nói chuyện lớn tiếng trong quầy. Để ý đổi nhạc và âm lượng cho hợp với không gian quán lúc đó.</li>\n</ol>","toc":[],"text":"Thử chất lượng trước khi ra chân gà hoặc món nước. Mỗi bịch chân gà đổ ra thùng để bán, bạn ra món dùng muỗng múc 1 chiếc ăn thử xem có bị lên men hay có mùi lạ không. Bịch nào cũng phải thử. Nước nấu cũng thử trước khi làm món. Có vấn đề thì ngưng ra món, báo quản lý ngay. Kiểm tra món trước khi đọc bàn. Đủ nước chấm, ớt, kẹo, bánh tráng, bánh đa cho những món cần có. Đọc bàn cho tiếp thực. Đọc rõ số bàn + tên món , chờ tiếp thực lặp lại rồi mới giao món. Đơn app và đơn mang về. Đủ muỗng đũa, nước chấm, bánh đa, bánh tráng; đối chiếu với hóa đơn một lần cuối rồi mới đưa tài xế. Rửa ly đúng cách. Lật đáy ly lên, dùng bàn chải chà đáy vì ly của quán dễ đóng cặn dơ dưới đáy. Thấy đáy ly đóng cặn đen thì báo quản lý liền. Sắp hết hàng giữa ca (nước chấm, phụ liệu, nước bán) → báo bộ đàm cho quản lý và phục vụ biết trước, đừng đợi hết hẳn mới nói. Giữ quầy yên. Không nói chuyện lớn tiếng trong quầy. Để ý đổi nhạc và âm lượng cho hợp với không gian quán lúc đó.","h":"e44fb504"},"quay3":{"so":"3","ten":"Cuối ca – giao quầy","nhan":"","html":"<ul>\n<li class=\"chk\">Vệ sinh quầy sạch, gọn. Không để ly hoặc dụng cụ còn nằm trong bồn rửa.</li>\n<li class=\"chk\">Dụng cụ ở vị trí nào để lại đúng vị trí đó, ca sau vào không phải đi tìm.</li>\n<li class=\"chk\">Ca 1 giao ca 2: nói rõ thứ gì đã châm, thứ gì còn thiếu hoặc đang làm dở.</li>\n<li class=\"chk\">Xong hết các việc trên đúng giờ quy định. Trường hợp đặc thù thì quản lý sắp xếp; không cà kê việc riêng làm chậm tiến độ.</li>\n<li class=\"chk\">Ca tối: chụp hình quầy đầy đủ, gửi nhóm Zalo.</li>\n</ul>","toc":[],"text":"Vệ sinh quầy sạch, gọn. Không để ly hoặc dụng cụ còn nằm trong bồn rửa. Dụng cụ ở vị trí nào để lại đúng vị trí đó, ca sau vào không phải đi tìm. Ca 1 giao ca 2: nói rõ thứ gì đã châm, thứ gì còn thiếu hoặc đang làm dở. Xong hết các việc trên đúng giờ quy định. Trường hợp đặc thù thì quản lý sắp xếp; không cà kê việc riêng làm chậm tiến độ. Ca tối: chụp hình quầy đầy đủ, gửi nhóm Zalo.","h":"69ce5eb5"},"quay4":{"so":"!","ten":"Trách nhiệm khi có lỗi","nhan":"","html":"<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Lỗi</th>\n<th>Ai chịu trách nhiệm</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Đáy ly đóng cặn đen mà không báo, quản lý tự phát hiện</td>\n<td>Bạn đứng quầy ca đó</td>\n</tr>\n<tr>\n<td>Ca chiều không báo thiếu hàng, trong ca bán bị thiếu</td>\n<td>Bạn đứng quầy ca chiều, không đổ cho ca sáng</td>\n</tr>\n<tr>\n<td>Không thử chân gà / nước nấu, hoặc thấy lạ mà không báo, đã ra cho khách</td>\n<td>Bạn ra món, xử lý theo nội quy quán</td>\n</tr>\n<tr>\n<td>Nói lớn hoặc quên chỉnh nhạc, bị nhắc từ 3 lần trở lên trong 1 ca</td>\n<td>20.000đ bỏ vào Heo</td>\n</tr>\n</tbody>\n</table></div>","toc":[],"text":"Lỗi Ai chịu trách nhiệm Đáy ly đóng cặn đen mà không báo, quản lý tự phát hiện Bạn đứng quầy ca đó Ca chiều không báo thiếu hàng, trong ca bán bị thiếu Bạn đứng quầy ca chiều, không đổ cho ca sáng Không thử chân gà / nước nấu, hoặc thấy lạ mà không báo, đã ra cho khách Bạn ra món, xử lý theo nội quy quán Nói lớn hoặc quên chỉnh nhạc, bị nhắc từ 3 lần trở lên trong 1 ca 20.000đ bỏ vào Heo","h":"d9a3b926"},"cachnoi":{"so":"★","ten":"Cách Gặm nói khi có chuyện","nhan":"","html":"<p>Khi khách không vui, khách cần thấy mình <strong>đứng về phía khách và đang làm liền</strong>, chứ không cần nghe giải thích dài.</p>\n<p><strong>Câu thần chú của Gặm:</strong> HIỂU → XIN LỖI → KIỂM TRA → XỬ LÝ → THEO TỚI CÙNG</p>\n<p><strong>5 nguyên tắc nói:</strong></p>\n<ol>\n<li><strong>Mở đầu bằng \"Dạ\", gọi khách là \"anh/chị\".</strong> Khách lớn tuổi gọi \"cô/chú\". Không gọi trống.</li>\n<li><strong>Câu ngắn, làm trước nói sau.</strong> Một câu xin lỗi + một việc làm ngay. Ví dụ: <em class=\"noi\">Dạ em xin lỗi anh, em thu món này lại liền nha.</em></li>\n<li><strong>Nói việc mình sẽ làm, không nói lý do của quán.</strong> Khách không cần biết bếp đông hay thiếu người; khách cần biết bao lâu nữa có món.</li>\n<li><strong>Chưa chắc thì hẹn giờ quay lại.</strong> <em class=\"noi\">Cho em 2 phút, em quay lại báo anh chị liền.</em> — và phải quay lại đúng hẹn.</li>\n<li><strong>Không hứa thay quản lý.</strong> Miễn món, giảm giá, tặng món là quản lý quyết. Nhân viên nói: <em class=\"noi\">Để em mời quản lý xuống lo cho anh chị nha.</em></li>\n</ol>\n<p><strong>Thay vì nói → Gặm nói:</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Đừng nói</th>\n<th>Gặm nói</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>\"Bếp đang đông lắm anh.\"</td>\n<td>\"Dạ em hối bếp làm trước món của anh liền nha.\"</td>\n</tr>\n<tr>\n<td>\"Không phải lỗi của em.\"</td>\n<td>\"Dạ để em lo chuyện này cho anh chị.\"</td>\n</tr>\n<tr>\n<td>\"Em đã xác nhận hóa đơn có sai sót.\"</td>\n<td>\"Dạ bill bị nhầm thật, em sửa liền.\"</td>\n</tr>\n<tr>\n<td>\"Ai cũng ăn vậy mà.\"</td>\n<td>\"Dạ món này chưa vừa miệng anh hả, anh thấy sao em nghe thử.\"</td>\n</tr>\n<tr>\n<td>\"Không được đâu anh.\"</td>\n<td>\"Dạ cái này Gặm chưa làm được, nhưng em có cách này cho anh…\"</td>\n</tr>\n<tr>\n<td>\"Chờ xíu.\"</td>\n<td>\"Dạ anh chị đợi em xíu, em quay lại liền ạ.\"</td>\n</tr>\n</tbody>\n</table></div>","toc":[],"text":"Khi khách không vui, khách cần thấy mình đứng về phía khách và đang làm liền , chứ không cần nghe giải thích dài. Câu thần chú của Gặm: HIỂU → XIN LỖI → KIỂM TRA → XỬ LÝ → THEO TỚI CÙNG 5 nguyên tắc nói: Mở đầu bằng \"Dạ\", gọi khách là \"anh/chị\". Khách lớn tuổi gọi \"cô/chú\". Không gọi trống. Câu ngắn, làm trước nói sau. Một câu xin lỗi + một việc làm ngay. Ví dụ: Dạ em xin lỗi anh, em thu món này lại liền nha. Nói việc mình sẽ làm, không nói lý do của quán. Khách không cần biết bếp đông hay thiếu người; khách cần biết bao lâu nữa có món. Chưa chắc thì hẹn giờ quay lại. Cho em 2 phút, em quay lại báo anh chị liền. — và phải quay lại đúng hẹn. Không hứa thay quản lý. Miễn món, giảm giá, tặng món là quản lý quyết. Nhân viên nói: Để em mời quản lý xuống lo cho anh chị nha. Thay vì nói → Gặm nói: Đừng nói Gặm nói \"Bếp đang đông lắm anh.\" \"Dạ em hối bếp làm trước món của anh liền nha.\" \"Không phải lỗi của em.\" \"Dạ để em lo chuyện này cho anh chị.\" \"Em đã xác nhận hóa đơn có sai sót.\" \"Dạ bill bị nhầm thật, em sửa liền.\" \"Ai cũng ăn vậy mà.\" \"Dạ món này chưa vừa miệng anh hả, anh thấy sao em nghe thử.\" \"Không được đâu anh.\" \"Dạ cái này Gặm chưa làm được, nhưng em có cách này cho anh…\" \"Chờ xíu.\" \"Dạ anh chị đợi em xíu, em quay lại liền ạ.\"","h":"3d19eda5"},"th1":{"so":"1","ten":"Món ra lâu","nhan":"","html":"<p><em>Khách: \"Gọi món 30 phút rồi mà chưa có, làm ăn kiểu gì vậy?\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> xem giờ order trên điện thoại, bộ đàm báo Bếp (bàn · món · order bao lâu · đang trễ), theo Quy trình 7 trong tài liệu Quy trình phục vụ.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ em xin lỗi anh để anh chờ lâu. Em kiểm tra món của anh liền nha.</em></li>\n<li><strong>Có giờ từ bếp:</strong> <em class=\"noi\">Dạ món của anh đang làm, khoảng 7 phút nữa lên. Em nhờ bếp làm trước cho anh rồi, có món là em mang ra liền.</em></li>\n<li><strong>Chưa rõ giờ:</strong> <em class=\"noi\">Dạ em đang hỏi bếp, anh cho em 2 phút em quay lại báo anh chính xác nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Bếp đang đông lắm anh.\" · \"Sắp có rồi anh\" khi chưa hỏi bếp.</p></div>","toc":[],"text":"Khách: \"Gọi món 30 phút rồi mà chưa có, làm ăn kiểu gì vậy?\" Làm ngay: xem giờ order trên điện thoại, bộ đàm báo Bếp (bàn · món · order bao lâu · đang trễ), theo Quy trình 7 trong tài liệu Quy trình phục vụ. Mở lời: Dạ em xin lỗi anh để anh chờ lâu. Em kiểm tra món của anh liền nha. Có giờ từ bếp: Dạ món của anh đang làm, khoảng 7 phút nữa lên. Em nhờ bếp làm trước cho anh rồi, có món là em mang ra liền. Chưa rõ giờ: Dạ em đang hỏi bếp, anh cho em 2 phút em quay lại báo anh chính xác nha. Không nói: \"Bếp đang đông lắm anh.\" · \"Sắp có rồi anh\" khi chưa hỏi bếp.","h":"bc9aafc0"},"th2":{"so":"2","ten":"Khách chê món không ngon","nhan":"","html":"<p><em>Khách: \"Món này dở quá, tôi không ăn được.\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> hỏi rõ món bị gì (mặn, nhạt, nguội, dai…). Không cãi, không bênh món.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ món này chưa vừa miệng anh hả? Anh thấy bị mặn, nhạt hay sao, anh nói em nghe để em báo bếp nha.</em></li>\n<li><strong>Món lỗi thật</strong> (mặn quá, nguội, chưa tới): <em class=\"noi\">Dạ em xin lỗi anh, món này bên em làm chưa tới. Anh muốn em đổi phần mới hay đổi qua món khác ạ?</em></li>\n<li><strong>Không hợp khẩu vị:</strong> <em class=\"noi\">Dạ em hiểu, khẩu vị mỗi người mỗi khác. Anh muốn thử món khác thì em gợi ý mấy món có ngôi sao, khách Gặm hay gọi nhất nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Món này bên em bán nhiều người ăn lắm.\" · \"Không ai phàn nàn hết.\" · \"Món này phải ăn vậy mới đúng vị.\"</p></div>\n<p><strong>Sau đó:</strong> báo bếp món nào bị chê và vì sao; ghi vào báo cáo tình huống cuối ngày.</p>","toc":[],"text":"Khách: \"Món này dở quá, tôi không ăn được.\" Làm ngay: hỏi rõ món bị gì (mặn, nhạt, nguội, dai…). Không cãi, không bênh món. Mở lời: Dạ món này chưa vừa miệng anh hả? Anh thấy bị mặn, nhạt hay sao, anh nói em nghe để em báo bếp nha. Món lỗi thật (mặn quá, nguội, chưa tới): Dạ em xin lỗi anh, món này bên em làm chưa tới. Anh muốn em đổi phần mới hay đổi qua món khác ạ? Không hợp khẩu vị: Dạ em hiểu, khẩu vị mỗi người mỗi khác. Anh muốn thử món khác thì em gợi ý mấy món có ngôi sao, khách Gặm hay gọi nhất nha. Không nói: \"Món này bên em bán nhiều người ăn lắm.\" · \"Không ai phàn nàn hết.\" · \"Món này phải ăn vậy mới đúng vị.\" Sau đó: báo bếp món nào bị chê và vì sao; ghi vào báo cáo tình huống cuối ngày.","h":"67af6ff2"},"th3":{"so":"3","ten":"Lên nhầm món","nhan":"","html":"<p><em>Khách: \"Tôi đâu có gọi món này.\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> mở order trên điện thoại ngay tại bàn.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ để em coi lại order liền cho anh nha.</em></li>\n<li><strong>Gặm lên nhầm:</strong> <em class=\"noi\">Dạ đúng là bên em lên nhầm, em xin lỗi anh. Em đổi lại món đúng cho anh liền.</em> → bộ đàm báo bếp ưu tiên món đúng.</li>\n<li><strong>Order ghi đúng món này:</strong> <em class=\"noi\">Dạ trong order em ghi món này, chắc lúc nãy em nghe chưa kỹ. Anh muốn món nào để em hỏi bếp liền nha.</em> Món đã làm thì đổi hay không do quản lý quyết.</li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Em nhớ là anh gọi món này mà.\" · \"Anh gọi rồi mà.\"</p></div>","toc":[],"text":"Khách: \"Tôi đâu có gọi món này.\" Làm ngay: mở order trên điện thoại ngay tại bàn. Mở lời: Dạ để em coi lại order liền cho anh nha. Gặm lên nhầm: Dạ đúng là bên em lên nhầm, em xin lỗi anh. Em đổi lại món đúng cho anh liền. → bộ đàm báo bếp ưu tiên món đúng. Order ghi đúng món này: Dạ trong order em ghi món này, chắc lúc nãy em nghe chưa kỹ. Anh muốn món nào để em hỏi bếp liền nha. Món đã làm thì đổi hay không do quản lý quyết. Không nói: \"Em nhớ là anh gọi món này mà.\" · \"Anh gọi rồi mà.\"","h":"2db1ea20"},"th4":{"so":"4","ten":"Nhân viên quên order món","nhan":"","html":"<p><em>Khách: \"Món của tôi đâu rồi?\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> nhập món liền, bộ đàm nhờ bếp làm trước, rồi quay lại bàn với giờ cụ thể.</p>\n<ul>\n<li><strong>Nhận lỗi:</strong> <em class=\"noi\">Dạ em xin lỗi anh, lúc nãy em sót món này. Em báo bếp làm trước cho anh rồi, khoảng 10 phút có món nha.</em></li>\n<li><strong>Khách rất bực:</strong> <em class=\"noi\">Dạ lỗi này là của em, em xin lỗi anh. Em mời quản lý xuống lo cho anh liền nha.</em></li>\n<li><strong>Khách không muốn chờ nữa:</strong> <em class=\"noi\">Dạ em hiểu. Em báo hủy món này cho anh, quản lý sẽ chỉnh lại bill giúp anh nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Tại lúc nãy đông quá.\" · \"Anh có gọi món này hả?\"</p></div>","toc":[],"text":"Khách: \"Món của tôi đâu rồi?\" Làm ngay: nhập món liền, bộ đàm nhờ bếp làm trước, rồi quay lại bàn với giờ cụ thể. Nhận lỗi: Dạ em xin lỗi anh, lúc nãy em sót món này. Em báo bếp làm trước cho anh rồi, khoảng 10 phút có món nha. Khách rất bực: Dạ lỗi này là của em, em xin lỗi anh. Em mời quản lý xuống lo cho anh liền nha. Khách không muốn chờ nữa: Dạ em hiểu. Em báo hủy món này cho anh, quản lý sẽ chỉnh lại bill giúp anh nha. Không nói: \"Tại lúc nãy đông quá.\" · \"Anh có gọi món này hả?\"","h":"7137be6c"},"th5":{"so":"5","ten":"Gà đốt Ô Thum / gà hấp mắm nhĩ còn máu","nhan":"","html":"<p><em>Khách: \"Gà còn máu nè, chưa chín mà đem ra cho khách ăn hả?\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> thu món, hỏi khách ăn chưa, báo quản lý và bếp. Không làm tiếp từ phần cũ.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ em xin lỗi anh. Em thu phần này lại liền. Anh ăn miếng nào chưa ạ?</em></li>\n<li><strong>Chưa ăn:</strong> <em class=\"noi\">Dạ may quá. Em báo bếp làm phần mới hoàn toàn, kiểm tra kỹ rồi mới mang ra cho anh. Anh muốn đổi món khác cũng được nha.</em></li>\n<li><strong>Đã ăn:</strong> <em class=\"noi\">Dạ anh ăn khoảng bao nhiêu rồi ạ? Giờ anh thấy trong người có sao không? Em mời quản lý xuống liền nha.</em></li>\n<li><strong>Quản lý:</strong> <em class=\"noi\">Dạ em là ___, quản lý ca hôm nay. Em xin lỗi anh về phần gà. Phần này bên em thu lại để kiểm tra; phần mới bếp làm lại từ đầu và em tự kiểm tra trước khi mang ra cho anh.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Gà này màu vậy là bình thường.\" · \"Chắc do xương.\" · \"Ăn miếng khác thử đi.\"</p></div>","toc":[],"text":"Khách: \"Gà còn máu nè, chưa chín mà đem ra cho khách ăn hả?\" Làm ngay: thu món, hỏi khách ăn chưa, báo quản lý và bếp. Không làm tiếp từ phần cũ. Mở lời: Dạ em xin lỗi anh. Em thu phần này lại liền. Anh ăn miếng nào chưa ạ? Chưa ăn: Dạ may quá. Em báo bếp làm phần mới hoàn toàn, kiểm tra kỹ rồi mới mang ra cho anh. Anh muốn đổi món khác cũng được nha. Đã ăn: Dạ anh ăn khoảng bao nhiêu rồi ạ? Giờ anh thấy trong người có sao không? Em mời quản lý xuống liền nha. Quản lý: Dạ em là ___, quản lý ca hôm nay. Em xin lỗi anh về phần gà. Phần này bên em thu lại để kiểm tra; phần mới bếp làm lại từ đầu và em tự kiểm tra trước khi mang ra cho anh. Không nói: \"Gà này màu vậy là bình thường.\" · \"Chắc do xương.\" · \"Ăn miếng khác thử đi.\"","h":"0f9128e9"},"th6":{"so":"6","ten":"Có dị vật trong món (kẽm chà xoong, tóc, sạn, côn trùng)","nhan":"","html":"<p><em>Khách: \"Trong món có cọng kẽm này! Nhà hàng làm ăn kiểu gì vậy?\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> dừng món, hỏi khách có bị đau không, <strong>giữ nguyên dĩa và dị vật</strong> (không đổ bỏ), chụp hình, báo quản lý.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ em xin lỗi anh. Anh khoan ăn tiếp nha. Anh có bị cào hay đau trong miệng không ạ?</em></li>\n<li><strong>Khách không sao:</strong> <em class=\"noi\">Dạ may quá anh không sao. Em giữ nguyên dĩa này để quản lý kiểm tra, em mời quản lý xuống liền nha.</em></li>\n<li><strong>Quản lý:</strong> <em class=\"noi\">Dạ em là ___, quản lý ca. Em xin lỗi anh về chuyện này. Phần này em giữ lại để kiểm tra từ bếp tới lúc ra món. Phần món này Gặm xin phép không tính tiền anh.</em> (quản lý quyết)</li>\n<li><strong>Chưa rõ nguyên nhân:</strong> <em class=\"noi\">Dạ bên em đang kiểm tra lại từ khâu sơ chế tới lúc ra món. Có kết quả em báo anh liền.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Chắc rớt từ trên cây xuống.\" · \"Ăn ở đâu cũng có lúc bị vậy.\"</p></div>\n<p><strong>Nếu khách bị thương:</strong> quản lý xử lý trực tiếp, hỗ trợ khách đi khám, ghi lại đầy đủ.</p>","toc":[],"text":"Khách: \"Trong món có cọng kẽm này! Nhà hàng làm ăn kiểu gì vậy?\" Làm ngay: dừng món, hỏi khách có bị đau không, giữ nguyên dĩa và dị vật (không đổ bỏ), chụp hình, báo quản lý. Mở lời: Dạ em xin lỗi anh. Anh khoan ăn tiếp nha. Anh có bị cào hay đau trong miệng không ạ? Khách không sao: Dạ may quá anh không sao. Em giữ nguyên dĩa này để quản lý kiểm tra, em mời quản lý xuống liền nha. Quản lý: Dạ em là ___, quản lý ca. Em xin lỗi anh về chuyện này. Phần này em giữ lại để kiểm tra từ bếp tới lúc ra món. Phần món này Gặm xin phép không tính tiền anh. (quản lý quyết) Chưa rõ nguyên nhân: Dạ bên em đang kiểm tra lại từ khâu sơ chế tới lúc ra món. Có kết quả em báo anh liền. Không nói: \"Chắc rớt từ trên cây xuống.\" · \"Ăn ở đâu cũng có lúc bị vậy.\" Nếu khách bị thương: quản lý xử lý trực tiếp, hỗ trợ khách đi khám, ghi lại đầy đủ.","h":"338aaf02"},"th7":{"so":"7","ten":"Khách chê đắt","nhan":"","html":"<p><em>Khách: \"Món có tí xíu mà bán giá này? Đắt quá!\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> nghe khách nói hết, không bênh giá. Ghi lại món nào bị chê để báo quản lý.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ em hiểu, nhìn phần món anh thấy chưa xứng đúng không ạ. Em ghi lại để báo quản lý xem lại phần món này nha.</em></li>\n<li><strong>Khách đang chọn món:</strong> <em class=\"noi\">Dạ bàn mình đi đông thì em gợi ý mấy món phần lớn ăn chung, sẽ vừa hơn cho mình ạ.</em></li>\n<li><strong>Có chương trình:</strong> <em class=\"noi\">Dạ để em coi bill mình có ưu đãi nào áp dụng được không nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Giá này là rẻ rồi anh.\" · \"Chỗ khác còn mắc hơn.\" · \"Giá ghi trên menu rồi mà.\"</p></div>","toc":[],"text":"Khách: \"Món có tí xíu mà bán giá này? Đắt quá!\" Làm ngay: nghe khách nói hết, không bênh giá. Ghi lại món nào bị chê để báo quản lý. Mở lời: Dạ em hiểu, nhìn phần món anh thấy chưa xứng đúng không ạ. Em ghi lại để báo quản lý xem lại phần món này nha. Khách đang chọn món: Dạ bàn mình đi đông thì em gợi ý mấy món phần lớn ăn chung, sẽ vừa hơn cho mình ạ. Có chương trình: Dạ để em coi bill mình có ưu đãi nào áp dụng được không nha. Không nói: \"Giá này là rẻ rồi anh.\" · \"Chỗ khác còn mắc hơn.\" · \"Giá ghi trên menu rồi mà.\"","h":"34e9dacc"},"th8":{"so":"8","ten":"Khách xin giảm giá hoặc miễn phí","nhan":"","html":"<p><em>Khách: \"Bớt cho chị 10% đi, chị ăn quán hoài mà.\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> không tự hứa. Hỏi quản lý.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ chị ghé Gặm hoài em vui lắm. Để em hỏi quản lý xem hôm nay hỗ trợ chị được gì nha.</em></li>\n<li><strong>Quản lý đồng ý:</strong> <em class=\"noi\">Dạ quản lý gửi chị phần ưu đãi này nha. Cảm ơn chị đã thương Gặm.</em></li>\n<li><strong>Không được:</strong> <em class=\"noi\">Dạ em hỏi rồi, lần này Gặm chưa giảm thêm được chị ạ. Gặm có chương trình gì là đăng trên fanpage, chị theo dõi giúp em nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Không được đâu chị.\" · \"Quán không giảm giá.\"</p></div>","toc":[],"text":"Khách: \"Bớt cho chị 10% đi, chị ăn quán hoài mà.\" Làm ngay: không tự hứa. Hỏi quản lý. Mở lời: Dạ chị ghé Gặm hoài em vui lắm. Để em hỏi quản lý xem hôm nay hỗ trợ chị được gì nha. Quản lý đồng ý: Dạ quản lý gửi chị phần ưu đãi này nha. Cảm ơn chị đã thương Gặm. Không được: Dạ em hỏi rồi, lần này Gặm chưa giảm thêm được chị ạ. Gặm có chương trình gì là đăng trên fanpage, chị theo dõi giúp em nha. Không nói: \"Không được đâu chị.\" · \"Quán không giảm giá.\"","h":"f46363a0"},"th9":{"so":"9","ten":"Khách phát hiện bill sai","nhan":"","html":"<p><em>Khách: \"Sao bill tính 3 chai bia, bàn tôi uống có 2 chai mà?\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> cầm bill dò từng món với khách ngay tại bàn. Bill đã in không xóa món được, nên cần quản lý xử lý.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ để em dò lại bill với anh từng món nha.</em></li>\n<li><strong>Tính dư:</strong> <em class=\"noi\">Dạ đúng là bill bị tính dư món này, em xin lỗi anh. Em báo quản lý sửa lại liền.</em></li>\n<li><strong>Khách báo tính thiếu:</strong> <em class=\"noi\">Dạ em cảm ơn anh đã báo giúp em. Em chỉnh lại bill cho đúng nha.</em></li>\n<li><strong>Bill đúng:</strong> <em class=\"noi\">Dạ em dò rồi, bill đúng với các món bàn mình đã lên. Anh coi giúp em có món nào anh chưa nhận không ạ?</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Máy tính mà sai sao được.\" · \"Em vừa kiểm tra và xác nhận hóa đơn đang có sai sót…\"</p></div>\n<p><strong>Phòng trước:</strong> làm đúng Quy trình 5 – kiểm tra bàn trước, in bill sau.</p>","toc":[],"text":"Khách: \"Sao bill tính 3 chai bia, bàn tôi uống có 2 chai mà?\" Làm ngay: cầm bill dò từng món với khách ngay tại bàn. Bill đã in không xóa món được, nên cần quản lý xử lý. Mở lời: Dạ để em dò lại bill với anh từng món nha. Tính dư: Dạ đúng là bill bị tính dư món này, em xin lỗi anh. Em báo quản lý sửa lại liền. Khách báo tính thiếu: Dạ em cảm ơn anh đã báo giúp em. Em chỉnh lại bill cho đúng nha. Bill đúng: Dạ em dò rồi, bill đúng với các món bàn mình đã lên. Anh coi giúp em có món nào anh chưa nhận không ạ? Không nói: \"Máy tính mà sai sao được.\" · \"Em vừa kiểm tra và xác nhận hóa đơn đang có sai sót…\" Phòng trước: làm đúng Quy trình 5 – kiểm tra bàn trước, in bill sau.","h":"6392a812"},"th10":{"so":"10","ten":"Khách nổi nóng, lớn tiếng","nhan":"","html":"<p><em>Khách: \"Làm ăn kiểu gì vậy? Có cái món cũng làm không xong!\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> đứng yên, nhìn khách, không ngắt lời. Để khách nói hết rồi mới đáp.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ em nghe anh nói nè. Anh cho em biết chuyện gì để em lo liền cho anh.</em></li>\n<li><strong>Sau khi nghe:</strong> <em class=\"noi\">Dạ em hiểu rồi, em xin lỗi anh. Em [việc cụ thể] liền, 2 phút em quay lại báo anh.</em></li>\n<li><strong>Vẫn lớn tiếng:</strong> <em class=\"noi\">Dạ em muốn lo cho anh nhanh nhất, để em mời quản lý xuống cùng xử lý với anh nha.</em></li>\n<li><strong>Khách xúc phạm nhân viên:</strong> nhân viên không đáp trả, nói một câu rồi lùi lại báo quản lý: <em class=\"noi\">Dạ em xin phép mời quản lý xuống nói chuyện với anh nha.</em></li>\n<li><strong>Quản lý:</strong> <em class=\"noi\">Dạ em là ___, quản lý ca. Em xin phép tiếp anh chuyện này. Anh nói em nghe, em lo cho anh.</em> Nếu ảnh hưởng bàn khác, quản lý mời khách qua chỗ riêng để nói chuyện.</li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Anh bình tĩnh đi.\" · \"Anh nói nhỏ thôi.\" · \"Đâu phải lỗi em.\"</p></div>\n<p><strong>Quy tắc cho nhân viên:</strong> bị xúc phạm thì được rút lui và giao cho quản lý. Không ai phải đứng nghe chửi một mình.</p>","toc":[],"text":"Khách: \"Làm ăn kiểu gì vậy? Có cái món cũng làm không xong!\" Làm ngay: đứng yên, nhìn khách, không ngắt lời. Để khách nói hết rồi mới đáp. Mở lời: Dạ em nghe anh nói nè. Anh cho em biết chuyện gì để em lo liền cho anh. Sau khi nghe: Dạ em hiểu rồi, em xin lỗi anh. Em [việc cụ thể] liền, 2 phút em quay lại báo anh. Vẫn lớn tiếng: Dạ em muốn lo cho anh nhanh nhất, để em mời quản lý xuống cùng xử lý với anh nha. Khách xúc phạm nhân viên: nhân viên không đáp trả, nói một câu rồi lùi lại báo quản lý: Dạ em xin phép mời quản lý xuống nói chuyện với anh nha. Quản lý: Dạ em là ___, quản lý ca. Em xin phép tiếp anh chuyện này. Anh nói em nghe, em lo cho anh. Nếu ảnh hưởng bàn khác, quản lý mời khách qua chỗ riêng để nói chuyện. Không nói: \"Anh bình tĩnh đi.\" · \"Anh nói nhỏ thôi.\" · \"Đâu phải lỗi em.\" Quy tắc cho nhân viên: bị xúc phạm thì được rút lui và giao cho quản lý. Không ai phải đứng nghe chửi một mình.","h":"fa6774a1"},"th11":{"so":"11","ten":"Khách yêu cầu ngoài quy định","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> nói \"chưa được\" bằng một câu, rồi đưa ngay một cách khác.</p>\n<ul>\n<li><strong>Khách muốn hút thuốc tại bàn:</strong> <em class=\"noi\">Dạ khu này Gặm không hút thuốc được anh ơi. Anh muốn hút thì em chỉ anh qua chỗ ___ nha, bên đó thoải mái hơn.</em></li>\n<li><strong>Khách muốn đổi món khi bếp đã làm:</strong> <em class=\"noi\">Dạ món này bếp làm xong rồi nên em không đổi được như lúc chưa làm. Anh muốn thử món khác thì em gợi ý anh nha; còn phần này để em hỏi quản lý xem hỗ trợ được gì.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Quy định rồi anh.\" · \"Không được đâu.\"</p></div>","toc":[],"text":"Làm ngay: nói \"chưa được\" bằng một câu, rồi đưa ngay một cách khác. Khách muốn hút thuốc tại bàn: Dạ khu này Gặm không hút thuốc được anh ơi. Anh muốn hút thì em chỉ anh qua chỗ ___ nha, bên đó thoải mái hơn. Khách muốn đổi món khi bếp đã làm: Dạ món này bếp làm xong rồi nên em không đổi được như lúc chưa làm. Anh muốn thử món khác thì em gợi ý anh nha; còn phần này để em hỏi quản lý xem hỗ trợ được gì. Không nói: \"Quy định rồi anh.\" · \"Không được đâu.\"","h":"fe64827d"},"th12":{"so":"12","ten":"Xoài (hoặc vật gì đó) rớt trúng khách","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> hỏi khách liền, gọi quản lý, mang khăn lạnh tới. Khách bị trúng đầu thì mời ngồi yên, đừng đứng dậy vội.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ anh có sao không? Anh đau chỗ nào, để em xem giúp anh.</em></li>\n<li><strong>Khách đau nhiều:</strong> <em class=\"noi\">Dạ anh ngồi yên giúp em nha, em gọi quản lý xuống liền.</em></li>\n<li><strong>Khách không sao:</strong> <em class=\"noi\">Dạ may quá anh không sao. Em đổi anh qua bàn khác nha, khu này bên em kiểm tra lại cây liền.</em></li>\n<li><strong>Quản lý:</strong> <em class=\"noi\">Dạ em là ___, quản lý ca. Em xin lỗi anh vì sự cố này. Chỗ bị trúng anh còn đau không? Khu này bên em tạm ngưng để kiểm tra, không cho khách khác ngồi vào.</em> Khách cần đi khám thì quản lý hỗ trợ.</li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Xui thôi ạ.\" · \"Tại anh ngồi ngay dưới cây.\" · \"Xoài tự rụng mà.\"</p></div>\n<p><strong>Phòng trước:</strong> đầu ca nhìn trái trên cây ở các khu có bàn bên dưới.</p>","toc":[],"text":"Làm ngay: hỏi khách liền, gọi quản lý, mang khăn lạnh tới. Khách bị trúng đầu thì mời ngồi yên, đừng đứng dậy vội. Mở lời: Dạ anh có sao không? Anh đau chỗ nào, để em xem giúp anh. Khách đau nhiều: Dạ anh ngồi yên giúp em nha, em gọi quản lý xuống liền. Khách không sao: Dạ may quá anh không sao. Em đổi anh qua bàn khác nha, khu này bên em kiểm tra lại cây liền. Quản lý: Dạ em là ___, quản lý ca. Em xin lỗi anh vì sự cố này. Chỗ bị trúng anh còn đau không? Khu này bên em tạm ngưng để kiểm tra, không cho khách khác ngồi vào. Khách cần đi khám thì quản lý hỗ trợ. Không nói: \"Xui thôi ạ.\" · \"Tại anh ngồi ngay dưới cây.\" · \"Xoài tự rụng mà.\" Phòng trước: đầu ca nhìn trái trên cây ở các khu có bàn bên dưới.","h":"2fc67934"},"th13":{"so":"13","ten":"Khách về nhà báo đau bụng, nghi trúng thực","nhan":"","html":"<p><em>Khách gọi: \"Tối qua tôi ăn ở quán, sáng nay bị đau bụng với nôn. Chắc chắn là đồ ăn của quán!\"</em></p>\n<p class=\"lam\"><strong>Làm ngay:</strong> hỏi sức khỏe trước, ghi lại thông tin, báo quản lý ngay trong ngày.</p>\n<ul>\n<li><strong>Mở lời:</strong> <em class=\"noi\">Dạ em nghe anh nói vậy em lo quá. Giờ anh thấy trong người sao rồi ạ? Anh đã đi khám chưa?</em></li>\n<li><strong>Ghi thông tin:</strong> <em class=\"noi\">Dạ để em báo quản lý tiếp nhận trực tiếp cho anh. Anh cho em xin số điện thoại, giờ anh ghé hôm qua, bàn mình đi mấy người và ăn những món nào nha.</em></li>\n<li><strong>Khách khẳng định do quán:</strong> <em class=\"noi\">Dạ anh đang mệt nên lo là phải. Bên em sẽ kiểm tra lại nghiêm túc, quản lý sẽ gọi lại cho anh.</em> (quản lý hẹn giờ gọi cụ thể)</li>\n<li><strong>Khách đòi bồi thường:</strong> <em class=\"noi\">Dạ em ghi nhận yêu cầu của anh. Chuyện này quản lý sẽ trao đổi trực tiếp với anh nha.</em></li>\n<li><strong>Triệu chứng nặng:</strong> <em class=\"noi\">Dạ anh đi khám trước giúp em nha, sức khỏe của anh là quan trọng nhất. Bên em sẽ liên lạc lại với anh.</em></li>\n<li><strong>Quản lý gọi lại:</strong> <em class=\"noi\">Dạ em là ___, quản lý Gặm. Em rất tiếc vì anh đang không khỏe. Bên em đang kiểm tra lại các món, nguyên liệu và ca làm hôm đó, và xem có khách nào khác bị tương tự không. Em sẽ tự theo vụ này và báo lại anh.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Anh có ăn gì ngoài quán nữa không?\" · \"Hôm qua khách khác ăn đâu có sao.\"</p></div>","toc":[],"text":"Khách gọi: \"Tối qua tôi ăn ở quán, sáng nay bị đau bụng với nôn. Chắc chắn là đồ ăn của quán!\" Làm ngay: hỏi sức khỏe trước, ghi lại thông tin, báo quản lý ngay trong ngày. Mở lời: Dạ em nghe anh nói vậy em lo quá. Giờ anh thấy trong người sao rồi ạ? Anh đã đi khám chưa? Ghi thông tin: Dạ để em báo quản lý tiếp nhận trực tiếp cho anh. Anh cho em xin số điện thoại, giờ anh ghé hôm qua, bàn mình đi mấy người và ăn những món nào nha. Khách khẳng định do quán: Dạ anh đang mệt nên lo là phải. Bên em sẽ kiểm tra lại nghiêm túc, quản lý sẽ gọi lại cho anh. (quản lý hẹn giờ gọi cụ thể) Khách đòi bồi thường: Dạ em ghi nhận yêu cầu của anh. Chuyện này quản lý sẽ trao đổi trực tiếp với anh nha. Triệu chứng nặng: Dạ anh đi khám trước giúp em nha, sức khỏe của anh là quan trọng nhất. Bên em sẽ liên lạc lại với anh. Quản lý gọi lại: Dạ em là ___, quản lý Gặm. Em rất tiếc vì anh đang không khỏe. Bên em đang kiểm tra lại các món, nguyên liệu và ca làm hôm đó, và xem có khách nào khác bị tương tự không. Em sẽ tự theo vụ này và báo lại anh. Không nói: \"Anh có ăn gì ngoài quán nữa không?\" · \"Hôm qua khách khác ăn đâu có sao.\"","h":"8102c584"},"th14":{"so":"14","ten":"Khách để lại review 1 sao","nhan":"","html":"<p class=\"lam\"><strong>Ai trả lời:</strong> quản lý hoặc anh Đạt. Nêu đúng chuyện khách kể, không dán một câu mẫu cho mọi review. Khách nói chưa đúng thì vẫn lịch sự và mời khách nhắn riêng, không tranh luận công khai.</p>\n<p><strong>Câu trả lời mẫu:</strong></p>\n<p><em class=\"noi\">Dạ Gặm xin lỗi anh/chị vì lần ghé quán vừa rồi chưa được như mong đợi. Gặm đã đọc kỹ góp ý về [điều khách nêu] và đang coi lại với bếp và anh em phục vụ ca hôm đó. Anh/chị nhắn giúp Gặm qua inbox fanpage để Gặm hỏi thêm và xin lỗi trực tiếp nha. Cảm ơn anh/chị đã nói thẳng để Gặm sửa.</em></p>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Khách nói sai sự thật!\" · \"Bên em có camera chứng minh…\" · \"Hôm đó quán đông nên…\"</p></div>","toc":[],"text":"Ai trả lời: quản lý hoặc anh Đạt. Nêu đúng chuyện khách kể, không dán một câu mẫu cho mọi review. Khách nói chưa đúng thì vẫn lịch sự và mời khách nhắn riêng, không tranh luận công khai. Câu trả lời mẫu: Dạ Gặm xin lỗi anh/chị vì lần ghé quán vừa rồi chưa được như mong đợi. Gặm đã đọc kỹ góp ý về [điều khách nêu] và đang coi lại với bếp và anh em phục vụ ca hôm đó. Anh/chị nhắn giúp Gặm qua inbox fanpage để Gặm hỏi thêm và xin lỗi trực tiếp nha. Cảm ơn anh/chị đã nói thẳng để Gặm sửa. Không nói: \"Khách nói sai sự thật!\" · \"Bên em có camera chứng minh…\" · \"Hôm đó quán đông nên…\"","h":"180be724"},"th15":{"so":"15","ten":"Hết bàn, khách phải chờ","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> ghi tên, số người, số điện thoại; hẹn thời gian; quá giờ hẹn thì quay lại báo khách.</p>\n<ul>\n<li><em class=\"noi\">Dạ Gặm xin chào anh chị! Hiện quán đang kín bàn, khoảng ___ phút nữa có bàn cho mình. Anh chị đợi được không ạ? Em mời anh chị ngồi chờ ở ___ nha.</em></li>\n<li><strong>Khách không chờ:</strong> <em class=\"noi\">Dạ em tiếc quá. Lần sau anh chị gọi đặt bàn trước giúp em, Gặm giữ bàn cho mình nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Hết bàn rồi anh.\" · \"Không biết bao lâu nữa.\"</p></div>","toc":[],"text":"Làm ngay: ghi tên, số người, số điện thoại; hẹn thời gian; quá giờ hẹn thì quay lại báo khách. Dạ Gặm xin chào anh chị! Hiện quán đang kín bàn, khoảng ___ phút nữa có bàn cho mình. Anh chị đợi được không ạ? Em mời anh chị ngồi chờ ở ___ nha. Khách không chờ: Dạ em tiếc quá. Lần sau anh chị gọi đặt bàn trước giúp em, Gặm giữ bàn cho mình nha. Không nói: \"Hết bàn rồi anh.\" · \"Không biết bao lâu nữa.\"","h":"8ba62ea4"},"th16":{"so":"16","ten":"Khách đã đặt bàn mà bàn chưa sẵn","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> báo quản lý ưu tiên dọn bàn đó; gửi menu cho khách xem trước trong lúc chờ.</p>\n<ul>\n<li><em class=\"noi\">Dạ em xin lỗi anh chị, bàn của mình đang dọn, khoảng ___ phút là xong. Em gửi menu anh chị xem trước, ngồi xuống là em order liền cho mình nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Bàn khách trước chưa về.\"</p></div>","toc":[],"text":"Làm ngay: báo quản lý ưu tiên dọn bàn đó; gửi menu cho khách xem trước trong lúc chờ. Dạ em xin lỗi anh chị, bàn của mình đang dọn, khoảng ___ phút là xong. Em gửi menu anh chị xem trước, ngồi xuống là em order liền cho mình nha. Không nói: \"Bàn khách trước chưa về.\"","h":"a9153905"},"th17":{"so":"17","ten":"Hết món giữa ca","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> Bếp báo bộ đàm \"hết món ___\" ngay khi biết, để cả đội phục vụ báo khách từ lúc order.</p>\n<ul>\n<li><strong>Lúc khách đang chọn:</strong> <em class=\"noi\">Dạ hôm nay món ___ hết sớm rồi anh ạ. Anh thích vị đó thì em gợi ý món ___, cũng được khách Gặm gọi nhiều nha.</em></li>\n<li><strong>Đã order rồi mới biết hết:</strong> <em class=\"noi\">Dạ em xin lỗi anh, bếp vừa báo món ___ hết rồi. Em bỏ món này khỏi order, anh muốn đổi qua món nào để em báo bếp làm trước cho anh nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Hết rồi.\" (rồi đứng im)</p></div>","toc":[],"text":"Làm ngay: Bếp báo bộ đàm \"hết món ___\" ngay khi biết, để cả đội phục vụ báo khách từ lúc order. Lúc khách đang chọn: Dạ hôm nay món ___ hết sớm rồi anh ạ. Anh thích vị đó thì em gợi ý món ___, cũng được khách Gặm gọi nhiều nha. Đã order rồi mới biết hết: Dạ em xin lỗi anh, bếp vừa báo món ___ hết rồi. Em bỏ món này khỏi order, anh muốn đổi qua món nào để em báo bếp làm trước cho anh nha. Không nói: \"Hết rồi.\" (rồi đứng im)","h":"55992726"},"th18":{"so":"18","ten":"Làm đổ nước hoặc món lên khách","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> dừng lại, xin lỗi, hỏi khách có bị nóng không, đưa khăn sạch cho khách tự lau (không tự lau người khách), dọn bàn, báo quản lý.</p>\n<ul>\n<li><em class=\"noi\">Dạ em xin lỗi anh, em vụng quá. Anh có bị nóng không ạ? Em lấy khăn sạch cho anh liền.</em></li>\n<li><strong>Món bị đổ:</strong> <em class=\"noi\">Dạ phần này em báo bếp làm lại cho anh nha.</em></li>\n<li><strong>Quản lý:</strong> hỏi thăm khách, quyết định hỗ trợ (tặng món, miễn món…). Khách bị bỏng thì xả nước mát chỗ bỏng và hỗ trợ đi khám nếu cần.</li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Tại anh quay người.\"</p></div>","toc":[],"text":"Làm ngay: dừng lại, xin lỗi, hỏi khách có bị nóng không, đưa khăn sạch cho khách tự lau (không tự lau người khách), dọn bàn, báo quản lý. Dạ em xin lỗi anh, em vụng quá. Anh có bị nóng không ạ? Em lấy khăn sạch cho anh liền. Món bị đổ: Dạ phần này em báo bếp làm lại cho anh nha. Quản lý: hỏi thăm khách, quyết định hỗ trợ (tặng món, miễn món…). Khách bị bỏng thì xả nước mát chỗ bỏng và hỗ trợ đi khám nếu cần. Không nói: \"Tại anh quay người.\"","h":"4cac5e92"},"th19":{"so":"19","ten":"Khách dị ứng hoặc ăn kiêng, hỏi thành phần món","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> không đoán. Hỏi bếp thành phần, ghi rõ trên order <strong>\"DỊ ỨNG ___\"</strong> và bộ đàm nhắc bếp.</p>\n<ul>\n<li><em class=\"noi\">Dạ anh dị ứng gì để em ghi rõ cho bếp ạ?</em></li>\n<li><strong>Chưa chắc món có thành phần đó không:</strong> <em class=\"noi\">Dạ món này em chưa chắc có ___ không, em hỏi bếp liền rồi báo anh nha.</em></li>\n<li><strong>Bếp không tách ra được:</strong> <em class=\"noi\">Dạ món này bếp không chắc bỏ hết được ___, em không dám để anh ăn. Em gợi ý anh món khác an toàn hơn nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Chắc không có đâu anh.\" · \"Ít thôi không sao.\"</p></div>","toc":[],"text":"Làm ngay: không đoán. Hỏi bếp thành phần, ghi rõ trên order \"DỊ ỨNG ___\" và bộ đàm nhắc bếp. Dạ anh dị ứng gì để em ghi rõ cho bếp ạ? Chưa chắc món có thành phần đó không: Dạ món này em chưa chắc có ___ không, em hỏi bếp liền rồi báo anh nha. Bếp không tách ra được: Dạ món này bếp không chắc bỏ hết được ___, em không dám để anh ăn. Em gợi ý anh món khác an toàn hơn nha. Không nói: \"Chắc không có đâu anh.\" · \"Ít thôi không sao.\"","h":"fdf9603b"},"th20":{"so":"20","ten":"Khách đi cùng trẻ nhỏ","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> hỏi độ cay khi bàn gọi món cay (chân gà sả ớt…), xếp bàn xa lối bưng món nếu được.</p>\n<ul>\n<li><em class=\"noi\">Dạ món chân gà sả ớt bên em cay, bé ăn cay được không ạ? Em hỏi bếp làm ít cay cho bé được không nha.</em></li>\n<li><strong>Bé chạy giỡn gần lối bưng món</strong> (nói với ba mẹ, không nói với bé): <em class=\"noi\">Dạ anh chị ơi, lối này bên em hay bưng đồ nóng, anh chị để ý bé giúp em kẻo bé bị phỏng nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Anh chị giữ con giùm đi.\"</p></div>","toc":[],"text":"Làm ngay: hỏi độ cay khi bàn gọi món cay (chân gà sả ớt…), xếp bàn xa lối bưng món nếu được. Dạ món chân gà sả ớt bên em cay, bé ăn cay được không ạ? Em hỏi bếp làm ít cay cho bé được không nha. Bé chạy giỡn gần lối bưng món (nói với ba mẹ, không nói với bé): Dạ anh chị ơi, lối này bên em hay bưng đồ nóng, anh chị để ý bé giúp em kẻo bé bị phỏng nha. Không nói: \"Anh chị giữ con giùm đi.\"","h":"af1243c7"},"th21":{"so":"21","ten":"Khách mang đồ ăn, đồ uống từ ngoài vào","nhan":"","html":"<p><strong>Hỏi quản lý trước:</strong> Gặm có cho mang bánh kem, rượu từ ngoài vào không, có thu phí không.</p>\n<ul>\n<li><strong>Nếu được:</strong> <em class=\"noi\">Dạ được anh, để em mang dao, dĩa cho bánh nha.</em></li>\n<li><strong>Nếu không:</strong> <em class=\"noi\">Dạ Gặm chưa nhận đồ uống mang từ ngoài vào anh ơi, em gửi lại giúp anh nha. Anh xem thêm menu nước bên em để em gợi ý.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Quán cấm mang đồ ngoài.\"</p></div>","toc":[],"text":"Hỏi quản lý trước: Gặm có cho mang bánh kem, rượu từ ngoài vào không, có thu phí không. Nếu được: Dạ được anh, để em mang dao, dĩa cho bánh nha. Nếu không: Dạ Gặm chưa nhận đồ uống mang từ ngoài vào anh ơi, em gửi lại giúp anh nha. Anh xem thêm menu nước bên em để em gợi ý. Không nói: \"Quán cấm mang đồ ngoài.\"","h":"f4a88d7f"},"th22":{"so":"22","ten":"Khách say, ồn ào làm phiền bàn khác","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> nhân viên không tranh cãi, báo quản lý. Không bán thêm bia rượu khi khách đã quá say; khách say muốn tự lái xe thì gợi ý gọi xe.</p>\n<ul>\n<li><strong>Quản lý với bàn ồn:</strong> <em class=\"noi\">Dạ anh ơi, em là ___, quản lý ca. Bàn mình đang vui quá, anh giúp em nói nhỏ lại xíu để mấy bàn kế bên cùng thoải mái nha. Em cảm ơn anh.</em></li>\n<li><strong>Với bàn bị làm phiền:</strong> <em class=\"noi\">Dạ em xin lỗi anh chị, em đã nhắc bàn bên rồi. Anh chị muốn đổi qua bàn yên hơn thì em sắp xếp liền nha.</em></li>\n<li><strong>Khách say muốn lái xe:</strong> <em class=\"noi\">Dạ để em gọi xe cho anh về nha, xe anh để lại em giữ giúp.</em> (quản lý xác nhận Gặm có giữ xe qua đêm không)</li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Mấy anh ồn quá.\"</p></div>","toc":[],"text":"Làm ngay: nhân viên không tranh cãi, báo quản lý. Không bán thêm bia rượu khi khách đã quá say; khách say muốn tự lái xe thì gợi ý gọi xe. Quản lý với bàn ồn: Dạ anh ơi, em là ___, quản lý ca. Bàn mình đang vui quá, anh giúp em nói nhỏ lại xíu để mấy bàn kế bên cùng thoải mái nha. Em cảm ơn anh. Với bàn bị làm phiền: Dạ em xin lỗi anh chị, em đã nhắc bàn bên rồi. Anh chị muốn đổi qua bàn yên hơn thì em sắp xếp liền nha. Khách say muốn lái xe: Dạ để em gọi xe cho anh về nha, xe anh để lại em giữ giúp. (quản lý xác nhận Gặm có giữ xe qua đêm không) Không nói: \"Mấy anh ồn quá.\"","h":"d38c3b36"},"th23":{"so":"23","ten":"Trời mưa lớn, khách đang ngồi khu ngoài trời","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> các bạn khu ngoài cùng dời khách và món vào trong; quản lý xếp chỗ nếu trong đã kín.</p>\n<ul>\n<li><em class=\"noi\">Dạ trời mưa lớn rồi, em dời anh chị vô trong nha. Món của mình em mang theo liền.</em></li>\n<li><strong>Trong đã kín:</strong> <em class=\"noi\">Dạ bên trong đang kín, anh chị đợi em vài phút, em ghép chỗ cho mình liền nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Hết chỗ rồi anh chị chịu khó.\"</p></div>","toc":[],"text":"Làm ngay: các bạn khu ngoài cùng dời khách và món vào trong; quản lý xếp chỗ nếu trong đã kín. Dạ trời mưa lớn rồi, em dời anh chị vô trong nha. Món của mình em mang theo liền. Trong đã kín: Dạ bên trong đang kín, anh chị đợi em vài phút, em ghép chỗ cho mình liền nha. Không nói: \"Hết chỗ rồi anh chị chịu khó.\"","h":"617f05f7"},"th24":{"so":"24","ten":"Khách đòi gặp quản lý hoặc chủ quán","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> mời quản lý ca xuống liền, không hỏi lại \"anh gặp làm gì\".</p>\n<ul>\n<li><strong>Nhân viên:</strong> <em class=\"noi\">Dạ em mời quản lý xuống liền cho anh nha.</em></li>\n<li><strong>Khách muốn gặp anh Đạt khi anh không có ở quán</strong> (quản lý nói): <em class=\"noi\">Dạ anh Đạt hôm nay không có ở quán, em là ___, quản lý ca được anh Đạt giao lo chuyện này. Anh nói em nghe, em xử lý cho anh và em báo lại anh Đạt.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Chủ không có đâu.\" · \"Gặp chủ làm gì anh.\"</p></div>","toc":[],"text":"Làm ngay: mời quản lý ca xuống liền, không hỏi lại \"anh gặp làm gì\". Nhân viên: Dạ em mời quản lý xuống liền cho anh nha. Khách muốn gặp anh Đạt khi anh không có ở quán (quản lý nói): Dạ anh Đạt hôm nay không có ở quán, em là ___, quản lý ca được anh Đạt giao lo chuyện này. Anh nói em nghe, em xử lý cho anh và em báo lại anh Đạt. Không nói: \"Chủ không có đâu.\" · \"Gặp chủ làm gì anh.\"","h":"18832c2f"},"th25":{"so":"25","ten":"Khách quên đồ","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> thấy đồ bỏ quên thì giao quản lý giữ, ghi lại bàn và giờ. Khách còn gần cổng thì chạy ra đưa liền.</p>\n<ul>\n<li><strong>Khách quay lại:</strong> <em class=\"noi\">Dạ đồ của anh đây, em giữ cho anh nè.</em></li>\n<li><strong>Khách gọi hỏi:</strong> <em class=\"noi\">Dạ anh cho em xin giờ anh ngồi và bàn nào, em kiểm tra rồi gọi lại anh liền nha.</em></li>\n</ul>","toc":[],"text":"Làm ngay: thấy đồ bỏ quên thì giao quản lý giữ, ghi lại bàn và giờ. Khách còn gần cổng thì chạy ra đưa liền. Khách quay lại: Dạ đồ của anh đây, em giữ cho anh nè. Khách gọi hỏi: Dạ anh cho em xin giờ anh ngồi và bàn nào, em kiểm tra rồi gọi lại anh liền nha.","h":"22593dd7"},"th26":{"so":"26","ten":"Khách chuyển khoản nhưng quán chưa thấy tiền về","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> xem màn hình chuyển khoản của khách, chụp lại (số tiền, giờ, mã giao dịch), báo quản lý. Quản lý quyết cho khách về trước hay chờ thêm.</p>\n<ul>\n<li><em class=\"noi\">Dạ anh chuyển rồi mà bên em chưa thấy báo, chắc ngân hàng đang chậm. Anh cho em chụp lại màn hình chuyển khoản giúp em nha, em báo quản lý liền.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Anh chưa chuyển đâu.\" · \"Anh chuyển lại đi.\"</p></div>","toc":[],"text":"Làm ngay: xem màn hình chuyển khoản của khách, chụp lại (số tiền, giờ, mã giao dịch), báo quản lý. Quản lý quyết cho khách về trước hay chờ thêm. Dạ anh chuyển rồi mà bên em chưa thấy báo, chắc ngân hàng đang chậm. Anh cho em chụp lại màn hình chuyển khoản giúp em nha, em báo quản lý liền. Không nói: \"Anh chưa chuyển đâu.\" · \"Anh chuyển lại đi.\"","h":"efc8c45c"},"th27":{"so":"27","ten":"Khách đi ra cổng mà chưa thanh toán","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> coi như khách quên. Đi theo, nói nhỏ, không la lớn trước mặt khách khác.</p>\n<ul>\n<li><em class=\"noi\">Dạ anh ơi, bàn mình chưa tính tiền ạ. Em mời anh qua tính giúp em nha.</em></li>\n<li><strong>Khách cố ý bỏ đi:</strong> không đuổi theo, không giữ người. Báo quản lý ngay, ghi lại bàn, giờ, đặc điểm khách; quản lý xem lại camera.</li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Anh định đi luôn hả?\"</p></div>","toc":[],"text":"Làm ngay: coi như khách quên. Đi theo, nói nhỏ, không la lớn trước mặt khách khác. Dạ anh ơi, bàn mình chưa tính tiền ạ. Em mời anh qua tính giúp em nha. Khách cố ý bỏ đi: không đuổi theo, không giữ người. Báo quản lý ngay, ghi lại bàn, giờ, đặc điểm khách; quản lý xem lại camera. Không nói: \"Anh định đi luôn hả?\"","h":"d8b6205e"},"th28":{"so":"28","ten":"Khách gọi thêm món lúc bếp sắp đóng","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> trước giờ đóng bếp khoảng ___ phút, đi từng bàn hỏi gọi thêm một lượt (giờ đóng bếp: ___).</p>\n<ul>\n<li><strong>Trước giờ đóng bếp:</strong> <em class=\"noi\">Dạ bếp Gặm nhận món tới ___ giờ, anh chị muốn gọi thêm món gì em ghi luôn một lượt nha.</em></li>\n<li><strong>Quá giờ:</strong> <em class=\"noi\">Dạ bếp bên em vừa nghỉ rồi anh ơi, em tiếc quá. Nước thì em vẫn lấy thêm cho anh được nha.</em> (quản lý xác nhận quầy nước nghỉ lúc nào)</li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Đóng bếp rồi.\" (rồi quay đi)</p></div>","toc":[],"text":"Làm ngay: trước giờ đóng bếp khoảng ___ phút, đi từng bàn hỏi gọi thêm một lượt (giờ đóng bếp: ___). Trước giờ đóng bếp: Dạ bếp Gặm nhận món tới ___ giờ, anh chị muốn gọi thêm món gì em ghi luôn một lượt nha. Quá giờ: Dạ bếp bên em vừa nghỉ rồi anh ơi, em tiếc quá. Nước thì em vẫn lấy thêm cho anh được nha. (quản lý xác nhận quầy nước nghỉ lúc nào) Không nói: \"Đóng bếp rồi.\" (rồi quay đi)","h":"d52bc41a"},"th29":{"so":"29","ten":"Đơn giao hàng (ShopeeFood, GrabFood) bị thiếu, sai hoặc đổ","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> xin hình đơn và hình món khách nhận, báo quản lý. Quản lý quyết giao bù hay hoàn tiền, và ghi lại lỗi để kiểm tra khâu đóng gói.</p>\n<ul>\n<li><em class=\"noi\">Dạ Gặm xin lỗi anh/chị vì đơn bị thiếu ___. Anh/chị gửi giúp Gặm hình đơn hàng và món nhận được nha, Gặm xử lý cho mình liền.</em></li>\n<li><strong>Sau khi quản lý quyết:</strong> <em class=\"noi\">Dạ Gặm gửi bù phần ___ cho anh/chị trong khoảng ___ phút nha. Một lần nữa Gặm xin lỗi mình.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Bên em đóng đủ rồi, chắc tài xế làm rơi.\"</p></div>\n<p><strong>Phòng trước:</strong> đối chiếu từng món với đơn trước khi giao cho tài xế.</p>","toc":[],"text":"Làm ngay: xin hình đơn và hình món khách nhận, báo quản lý. Quản lý quyết giao bù hay hoàn tiền, và ghi lại lỗi để kiểm tra khâu đóng gói. Dạ Gặm xin lỗi anh/chị vì đơn bị thiếu ___. Anh/chị gửi giúp Gặm hình đơn hàng và món nhận được nha, Gặm xử lý cho mình liền. Sau khi quản lý quyết: Dạ Gặm gửi bù phần ___ cho anh/chị trong khoảng ___ phút nha. Một lần nữa Gặm xin lỗi mình. Không nói: \"Bên em đóng đủ rồi, chắc tài xế làm rơi.\" Phòng trước: đối chiếu từng món với đơn trước khi giao cho tài xế.","h":"7c70a93c"},"th30":{"so":"30","ten":"Khách quay video hoặc livestream phàn nàn ngay tại quán","nhan":"","html":"<p class=\"lam\"><strong>Làm ngay:</strong> không giành điện thoại, không yêu cầu tắt máy. Xử lý chuyện của khách như bình thường, lịch sự hơn nữa, mời quản lý xuống. Xong việc thì báo anh Đạt để theo dõi trên mạng.</p>\n<ul>\n<li><em class=\"noi\">Dạ em hiểu anh đang không hài lòng. Em mời quản lý xuống lo cho anh liền nha.</em></li>\n</ul>\n<div class=\"khong\"><p><strong>Không nói:</strong> \"Anh tắt máy đi.\" · \"Không được quay trong quán.\"</p></div>","toc":[],"text":"Làm ngay: không giành điện thoại, không yêu cầu tắt máy. Xử lý chuyện của khách như bình thường, lịch sự hơn nữa, mời quản lý xuống. Xong việc thì báo anh Đạt để theo dõi trên mạng. Dạ em hiểu anh đang không hài lòng. Em mời quản lý xuống lo cho anh liền nha. Không nói: \"Anh tắt máy đi.\" · \"Không được quay trong quán.\"","h":"6a706f8c"},"tranhanh":{"so":"!","ten":"Khi nào gọi quản lý","nhan":"Quản lý","html":"<p>Có người bị thương, chuyện vệ sinh an toàn thực phẩm, chuyện tiền hoặc chuyện lên mạng thì gọi quản lý ngay. Còn lại nhân viên xử lý trước, cuối ca báo lại.</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Mức</th>\n<th>Tình huống</th>\n<th>Ai xử lý</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nhân viên tự xử lý</td>\n<td>Món ra lâu (khách hỏi lần đầu), chê không hợp khẩu vị, lên nhầm món, hết món, hết bàn, khách quên đồ, dời khách khi mưa</td>\n<td>Nhân viên, cuối ca báo quản lý</td>\n</tr>\n<tr>\n<td>Xử lý trước rồi mời quản lý</td>\n<td>Khách hỏi món lần hai, khách vẫn lớn tiếng, xin giảm giá, bill sai, đổi món khi bếp đã làm, làm đổ đồ lên khách, khách say ồn ào, chuyển khoản chưa về, đơn giao hàng lỗi</td>\n<td>Nhân viên mở lời, quản lý quyết</td>\n</tr>\n<tr>\n<td>Gọi quản lý ngay</td>\n<td>Dị vật trong món, gà chưa chín, khách bị thương hoặc bỏng, nghi trúng thực, khách xúc phạm nhân viên, quay video phàn nàn, bỏ đi không thanh toán, đòi gặp chủ, đòi bồi thường</td>\n<td>Quản lý trực tiếp, báo anh Đạt</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Sau mỗi tình huống:</strong> ghi vào báo cáo tình huống hằng ngày (bàn nào, chuyện gì, đã xử lý ra sao) để họp thứ Hai cùng xem lại.</p>","toc":[],"text":"Có người bị thương, chuyện vệ sinh an toàn thực phẩm, chuyện tiền hoặc chuyện lên mạng thì gọi quản lý ngay. Còn lại nhân viên xử lý trước, cuối ca báo lại. Mức Tình huống Ai xử lý Nhân viên tự xử lý Món ra lâu (khách hỏi lần đầu), chê không hợp khẩu vị, lên nhầm món, hết món, hết bàn, khách quên đồ, dời khách khi mưa Nhân viên, cuối ca báo quản lý Xử lý trước rồi mời quản lý Khách hỏi món lần hai, khách vẫn lớn tiếng, xin giảm giá, bill sai, đổi món khi bếp đã làm, làm đổ đồ lên khách, khách say ồn ào, chuyển khoản chưa về, đơn giao hàng lỗi Nhân viên mở lời, quản lý quyết Gọi quản lý ngay Dị vật trong món, gà chưa chín, khách bị thương hoặc bỏng, nghi trúng thực, khách xúc phạm nhân viên, quay video phàn nàn, bỏ đi không thanh toán, đòi gặp chủ, đòi bồi thường Quản lý trực tiếp, báo anh Đạt Sau mỗi tình huống: ghi vào báo cáo tình huống hằng ngày (bàn nào, chuyện gì, đã xử lý ra sao) để họp thứ Hai cùng xem lại.","h":"efe9a0dd"},"baocao":{"so":"✎","ten":"Báo cáo tình huống cuối ngày","nhan":"Quản lý","html":"<p>Mỗi tối, quản lý ca ghi lại mọi tình huống trong ngày và tình hình bếp, gửi vào Báo cáo tình huống <strong>trước 23h</strong> để anh Đạt đọc.</p>\n<p class=\"lam\"><strong>Ai ghi:</strong> quản lý ca trực tiếp ghi, không giao lại cho nhân viên.</p>\n<p><strong>Gửi ở đâu:</strong> app Cẩm nang tình huống Gặm → tab <strong>✍️ Báo cáo hôm nay</strong>. Lúc 23h hệ thống tự tổng hợp, nên báo cáo gửi sau 23h sẽ lọt qua ngày hôm sau.</p>\n<p><strong>Các bước:</strong></p>\n<ol>\n<li><strong>Trong ca – ghi nhanh ngay khi có chuyện.</strong> Bàn nào, mấy giờ, chuyện gì, khách nói gì. Ghi vài chữ trên điện thoại là đủ, để cuối ngày không phải nhớ lại. Nhân viên báo quản lý mọi tình huống thuộc mức 2 và 3 trong bảng tra nhanh.</li>\n<li><strong>Cuối ca – hỏi nhanh đội phục vụ và bếp</strong> (khoảng 5 phút): <em class=\"noi\">Hôm nay có bàn nào không vui không? Bếp có trục trặc gì không?</em></li>\n<li><strong>Ghi từng tình huống.</strong> Mỗi tình huống một báo cáo riêng (loại \"Tình huống\"), đủ 6 ý trong bảng dưới.</li>\n<li><strong>Ghi tình hình bếp hôm nay</strong> theo bảng thứ hai.</li>\n<li><strong>Gửi trước 23h.</strong> Ngày không có tình huống nào vẫn gửi: <em class=\"noi\">Hôm nay không có tình huống</em> kèm tình hình bếp.</li>\n<li><strong>Theo tiếp ngày hôm sau.</strong> Tình huống chưa xong (khách chưa hài lòng, hẹn gọi lại khách, chờ kiểm tra nguyên nhân) thì quản lý ghi rõ \"đang theo\" và cập nhật trong báo cáo hôm sau.</li>\n</ol>\n<p><strong>Mỗi tình huống ghi đủ 6 ý:</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Mục</th>\n<th>Ghi gì</th>\n<th>Ví dụ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Chuyện gì xảy ra</td>\n<td>Bàn, giờ, món, chuyện gì</td>\n<td>Bàn B1, 19h30, gà đốt ra trễ khoảng 25 phút</td>\n</tr>\n<tr>\n<td>2. Khách cảm thấy lúc đầu</td>\n<td>Thái độ, lời khách nói</td>\n<td>Khách bực, hỏi món lần hai: \"Sao lâu vậy em?\"</td>\n</tr>\n<tr>\n<td>3. Đã xử lý thế nào</td>\n<td>Ai làm gì, đã nói gì với khách</td>\n<td>Phục vụ báo bếp, quản lý nhắc bạn phụ trách gà, xuống xin lỗi khách</td>\n</tr>\n<tr>\n<td>4. Khách cảm thấy sau khi xử lý</td>\n<td>Khách vui vẻ / Tạm ổn / Chưa hài lòng / Khách bỏ về, kèm lời khách nếu có</td>\n<td>Tạm ổn – khách ăn hết, lúc về có cười</td>\n</tr>\n<tr>\n<td>5. Vì sao xảy ra</td>\n<td>Nguyên nhân thật, không đổ lỗi</td>\n<td>Bếp nướng dồn nhiều phần gà cùng lúc</td>\n</tr>\n<tr>\n<td>6. Lần sau làm gì</td>\n<td>Đề xuất để khỏi lặp lại</td>\n<td>Lúc đông bếp báo bộ đàm trước món gà ra chậm</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Tình hình bếp hôm nay:</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Mục</th>\n<th>Ghi gì</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Món ra trễ</td>\n<td>Món nào, mấy lần, vào giờ nào</td>\n</tr>\n<tr>\n<td>Hết món</td>\n<td>Món nào hết, hết lúc mấy giờ</td>\n</tr>\n<tr>\n<td>Sự cố</td>\n<td>Hết gas, thiết bị hư, món phải làm lại</td>\n</tr>\n<tr>\n<td>Người làm</td>\n<td>Thiếu người, nghỉ đột xuất, ai làm tốt</td>\n</tr>\n<tr>\n<td>Nguyên liệu</td>\n<td>Cần đặt thêm, nguyên liệu không đạt</td>\n</tr>\n<tr>\n<td>Ghi chú khác</td>\n<td>Chuyện bếp muốn anh Đạt biết</td>\n</tr>\n</tbody>\n</table></div>\n<p>App hiện chưa có ô riêng cho tình hình bếp. Trong lúc chờ, quản lý gửi một báo cáo loại \"Góp ý\" với tiêu đề <em class=\"noi\">Tình hình bếp ngày ___</em> theo mẫu dưới.</p>\n<p><strong>Mẫu để chép nhanh:</strong></p>\n<p>```\nBÁO CÁO CUỐI NGÀY – Ngày ___ – Quản lý: ___</p>\n<p>TÌNH HUỐNG 1\n- Chuyện gì: \n- Khách lúc đầu: \n- Đã xử lý: \n- Khách sau khi xử lý: \n- Vì sao: \n- Lần sau: </p>\n<p>TÌNH HÌNH BẾP\n- Món ra trễ: \n- Hết món: \n- Sự cố: \n- Người làm: \n- Nguyên liệu: \n- Ghi chú: \n```</p>\n<p><strong>Quy tắc viết:</strong></p>\n<ul>\n<li>Ghi đúng sự thật và đúng lời khách nói, kể cả khi mình xử lý chưa tốt. Báo cáo để cả quán học, không phải để phạt.</li>\n<li>Viết ngắn, mỗi ý một hai câu.</li>\n<li>Chuyện liên quan lỗi của một bạn cụ thể thì tick <strong>\"Chỉ anh Đạt đọc\"</strong>.</li>\n<li>Tình huống nghiêm trọng (khách bị thương, nghi trúng thực, dị vật, quay video) thì gọi hoặc nhắn anh Đạt ngay lúc xảy ra, cuối ngày vẫn ghi báo cáo đầy đủ.</li>\n</ul>\n<p><strong>Sau đó:</strong> anh Đạt đọc lúc 23h trên Gặm Điều Hành. Cách xử lý tốt được duyệt vào cẩm nang cho cả quán; chuyện lặp lại nhiều lần đưa ra họp thứ Hai.</p>","toc":[],"text":"Mỗi tối, quản lý ca ghi lại mọi tình huống trong ngày và tình hình bếp, gửi vào Báo cáo tình huống trước 23h để anh Đạt đọc. Ai ghi: quản lý ca trực tiếp ghi, không giao lại cho nhân viên. Gửi ở đâu: app Cẩm nang tình huống Gặm → tab ✍️ Báo cáo hôm nay . Lúc 23h hệ thống tự tổng hợp, nên báo cáo gửi sau 23h sẽ lọt qua ngày hôm sau. Các bước: Trong ca – ghi nhanh ngay khi có chuyện. Bàn nào, mấy giờ, chuyện gì, khách nói gì. Ghi vài chữ trên điện thoại là đủ, để cuối ngày không phải nhớ lại. Nhân viên báo quản lý mọi tình huống thuộc mức 2 và 3 trong bảng tra nhanh. Cuối ca – hỏi nhanh đội phục vụ và bếp (khoảng 5 phút): Hôm nay có bàn nào không vui không? Bếp có trục trặc gì không? Ghi từng tình huống. Mỗi tình huống một báo cáo riêng (loại \"Tình huống\"), đủ 6 ý trong bảng dưới. Ghi tình hình bếp hôm nay theo bảng thứ hai. Gửi trước 23h. Ngày không có tình huống nào vẫn gửi: Hôm nay không có tình huống kèm tình hình bếp. Theo tiếp ngày hôm sau. Tình huống chưa xong (khách chưa hài lòng, hẹn gọi lại khách, chờ kiểm tra nguyên nhân) thì quản lý ghi rõ \"đang theo\" và cập nhật trong báo cáo hôm sau. Mỗi tình huống ghi đủ 6 ý: Mục Ghi gì Ví dụ 1. Chuyện gì xảy ra Bàn, giờ, món, chuyện gì Bàn B1, 19h30, gà đốt ra trễ khoảng 25 phút 2. Khách cảm thấy lúc đầu Thái độ, lời khách nói Khách bực, hỏi món lần hai: \"Sao lâu vậy em?\" 3. Đã xử lý thế nào Ai làm gì, đã nói gì với khách Phục vụ báo bếp, quản lý nhắc bạn phụ trách gà, xuống xin lỗi khách 4. Khách cảm thấy sau khi xử lý Khách vui vẻ / Tạm ổn / Chưa hài lòng / Khách bỏ về, kèm lời khách nếu có Tạm ổn – khách ăn hết, lúc về có cười 5. Vì sao xảy ra Nguyên nhân thật, không đổ lỗi Bếp nướng dồn nhiều phần gà cùng lúc 6. Lần sau làm gì Đề xuất để khỏi lặp lại Lúc đông bếp báo bộ đàm trước món gà ra chậm Tình hình bếp hôm nay: Mục Ghi gì Món ra trễ Món nào, mấy lần, vào giờ nào Hết món Món nào hết, hết lúc mấy giờ Sự cố Hết gas, thiết bị hư, món phải làm lại Người làm Thiếu người, nghỉ đột xuất, ai làm tốt Nguyên liệu Cần đặt thêm, nguyên liệu không đạt Ghi chú khác Chuyện bếp muốn anh Đạt biết App hiện chưa có ô riêng cho tình hình bếp. Trong lúc chờ, quản lý gửi một báo cáo loại \"Góp ý\" với tiêu đề Tình hình bếp ngày ___ theo mẫu dưới. Mẫu để chép nhanh: ``` BÁO CÁO CUỐI NGÀY – Ngày ___ – Quản lý: ___ TÌNH HUỐNG 1 - Chuyện gì: - Khách lúc đầu: - Đã xử lý: - Khách sau khi xử lý: - Vì sao: - Lần sau: TÌNH HÌNH BẾP - Món ra trễ: - Hết món: - Sự cố: - Người làm: - Nguyên liệu: - Ghi chú: ``` Quy tắc viết: Ghi đúng sự thật và đúng lời khách nói, kể cả khi mình xử lý chưa tốt. Báo cáo để cả quán học, không phải để phạt. Viết ngắn, mỗi ý một hai câu. Chuyện liên quan lỗi của một bạn cụ thể thì tick \"Chỉ anh Đạt đọc\" . Tình huống nghiêm trọng (khách bị thương, nghi trúng thực, dị vật, quay video) thì gọi hoặc nhắn anh Đạt ngay lúc xảy ra, cuối ngày vẫn ghi báo cáo đầy đủ. Sau đó: anh Đạt đọc lúc 23h trên Gặm Điều Hành. Cách xử lý tốt được duyệt vào cẩm nang cho cả quán; chuyện lặp lại nhiều lần đưa ra họp thứ Hai.","h":"e4889fb7"}}};
